                            <script>
                            document.addEventListener('DOMContentLoaded', function () {
                            const layout = document.querySelector('.layout');
                            const sidebar = document.getElementById('customerSidebar');
                            const contentStation = document.querySelector('.contentStation');
                            const rightPanel = document.querySelector('.right-panel');

                            const mainBtn = document.getElementById('mainContentToggle');
                            const noteFullscreenBtn = document.getElementById('btnToggleRightPanelFullscreen');
                            const noteHideBtn = document.getElementById('btnToggleRightPanelHidden');
                            const noteShowBtn = document.getElementById('showRightPanelBtn');

                            if (!layout || !sidebar || !contentStation || !rightPanel) return;

                            let sidebarManuallyChanged = false;

                            function refreshIcons() {
                                if (window.feather) {
                                    window.feather.replace();
                                }
                            }

                            function setIcon(button, featherName, fallbackClass) {
                                if (!button) return;

                                const oldIcon = button.querySelector('i, svg');
                                if (!oldIcon) return;

                                const icon = document.createElement('i');
                                icon.setAttribute('data-feather', featherName);

                                if (fallbackClass) {
                                    icon.className = 'feather ' + fallbackClass;
                                }

                                oldIcon.replaceWith(icon);
                                refreshIcons();
                            }

                            function closeSidebarLists() {
                                document.querySelectorAll('.product-list').forEach(function (el) {
                                    el.classList.remove('show');
                                    el.style.display = 'none';
                                    el.setAttribute('aria-expanded', 'false');
                                });

                                document.querySelectorAll('.sub-nav').forEach(function (el) {
                                    el.classList.remove('show');
                                    el.style.display = 'none';
                                    el.setAttribute('aria-expanded', 'false');
                                });

                                document.querySelectorAll('.project-link').forEach(function (el) {
                                    el.classList.remove('active');
                                });
                            }

                            function minimizeCustomerSidebar() {
                                resetFullscreenModes(false);

                                layout.classList.add('sidebar-minimized');
                                sidebar.classList.add('minimized');
                                contentStation.classList.add('expanded');

                                closeSidebarLists();

                                setIcon(sidebar.querySelector('.minimize-btn'), 'chevrons-right', 'icon-chevrons-right');

                                sidebarManuallyChanged = true;
                                refreshIcons();
                            }

                            function expandCustomerSidebar() {
                                layout.classList.remove('sidebar-minimized');
                                sidebar.classList.remove('minimized');
                                contentStation.classList.remove('expanded');

                                setIcon(sidebar.querySelector('.minimize-btn'), 'chevrons-left', 'icon-chevrons-left');

                                sidebarManuallyChanged = true;
                                refreshIcons();
                            }

                            window.togglecustomerSidebar = function () {
                                if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                    expandCustomerSidebar();
                                } else {
                                    minimizeCustomerSidebar();
                                }
                            };

                            function autoSidebarMode() {
                                if (sidebarManuallyChanged) return;

                                if (window.innerWidth < 992) {
                                    minimizeCustomerSidebar();
                                    sidebarManuallyChanged = false;
                                } else {
                                    expandCustomerSidebar();
                                    sidebarManuallyChanged = false;
                                }
                            }

                            function resetFullscreenModes(restoreIcons = true) {
                                layout.classList.remove('main-fullscreen-mode');
                                layout.classList.remove('notes-fullscreen-mode');

                                contentStation.classList.remove('main-fullscreen');
                                rightPanel.classList.remove('notes-fullscreen');

                                sidebar.classList.remove('fullscreen-hidden');
                                contentStation.classList.remove('fullscreen-hidden');
                                rightPanel.classList.remove('fullscreen-hidden');

                                if (restoreIcons) {
                                    setIcon(mainBtn, 'maximize-2', 'icon-maximize-2');
                                    setIcon(noteFullscreenBtn, 'maximize-2', 'icon-maximize-2');
                                }
                            }

                            function showNotesPanel() {
                                layout.classList.remove('notes-hidden-mode');
                                rightPanel.classList.remove('right-hidden');

                                if (noteShowBtn) {
                                    noteShowBtn.classList.add('d-none');
                                }

                                setIcon(noteHideBtn, 'sidebar', 'icon-sidebar');
                                refreshIcons();
                            }

                            function hideNotesPanel() {
                                resetFullscreenModes();

                                layout.classList.add('notes-hidden-mode');
                                rightPanel.classList.add('right-hidden');

                                if (noteShowBtn) {
                                    noteShowBtn.classList.remove('d-none');
                                }

                                setIcon(noteHideBtn, 'message-square', 'icon-message-square');
                                refreshIcons();
                            }

                            window.resetCustomerProfileFullscreen = resetFullscreenModes;
                            window.showCustomerNotesPanel = showNotesPanel;
                            window.hideCustomerNotesPanel = hideNotesPanel;
                            window.minimizeCustomerSidebar = minimizeCustomerSidebar;
                            window.expandCustomerSidebar = expandCustomerSidebar;

                            if (mainBtn) {
                                mainBtn.addEventListener('click', function (event) {
                                    event.preventDefault();
                                    event.stopPropagation();

                                    const isAlreadyFullscreen = layout.classList.contains('main-fullscreen-mode');

                                    resetFullscreenModes();

                                    if (!isAlreadyFullscreen) {
                                        showNotesPanel();

                                        layout.classList.add('main-fullscreen-mode');
                                        contentStation.classList.add('main-fullscreen');

                                        sidebar.classList.add('fullscreen-hidden');
                                        rightPanel.classList.add('fullscreen-hidden');

                                        setIcon(mainBtn, 'minimize-2', 'icon-minimize-2');
                                    }
                                });
                            }

                            if (noteFullscreenBtn) {
                                noteFullscreenBtn.addEventListener('click', function (event) {
                                    event.preventDefault();
                                    event.stopPropagation();

                                    const isAlreadyFullscreen = layout.classList.contains('notes-fullscreen-mode');

                                    resetFullscreenModes();

                                    if (!isAlreadyFullscreen) {
                                        showNotesPanel();

                                        layout.classList.add('notes-fullscreen-mode');
                                        rightPanel.classList.add('notes-fullscreen');

                                        sidebar.classList.add('fullscreen-hidden');
                                        contentStation.classList.add('fullscreen-hidden');

                                        setIcon(noteFullscreenBtn, 'minimize-2', 'icon-minimize-2');
                                    }
                                });
                            }

                            if (noteHideBtn) {
                                noteHideBtn.addEventListener('click', function (event) {
                                    event.preventDefault();
                                    event.stopPropagation();

                                    if (layout.classList.contains('notes-hidden-mode')) {
                                        showNotesPanel();
                                    } else {
                                        hideNotesPanel();
                                    }
                                });
                            }

                            if (noteShowBtn) {
                                noteShowBtn.addEventListener('click', function (event) {
                                    event.preventDefault();
                                    event.stopPropagation();

                                    showNotesPanel();
                                });
                            }

                            document.addEventListener('click', function (event) {
                                const shouldExpandSidebar =
                                    event.target.closest('.object-header') ||
                                    event.target.closest('.dashboard-btn');

                                if (
                                    shouldExpandSidebar &&
                                    (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized'))
                                ) {
                                    expandCustomerSidebar();
                                }
                            });

                            window.toggleObject = function (id) {
                                const target = document.getElementById(id);
                                if (!target) return;

                                if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                    expandCustomerSidebar();
                                }

                                const isOpen = target.classList.contains('show') || target.style.display === 'block';

                                document.querySelectorAll('.product-list').forEach(function (el) {
                                    el.classList.remove('show');
                                    el.style.display = 'none';
                                });

                                document.querySelectorAll('.sub-nav').forEach(function (el) {
                                    el.classList.remove('show');
                                    el.style.display = 'none';
                                });

                                document.querySelectorAll('.project-link').forEach(function (el) {
                                    el.classList.remove('active');
                                });

                                if (!isOpen) {
                                    target.classList.add('show');
                                    target.style.display = 'block';
                                    target.setAttribute('aria-expanded', 'true');
                                } else {
                                    target.classList.remove('show');
                                    target.style.display = 'none';
                                    target.setAttribute('aria-expanded', 'false');
                                }

                                refreshIcons();
                            };

                            window.toggleProduct = function (productKey) {
                                const subNav = document.getElementById(productKey);
                                const clicked = document.querySelector(`.project-link[data-product-key="${productKey}"]`);
                                const parentId = productKey.match(/product(\d+)_\d+/)?.[1];
                                const parentObjectList = document.getElementById(`object${parentId}`);
                                const title = document.getElementById('note_title');

                                if (title) title.textContent = 'NOTIZEN';

                                if (!subNav || !clicked || !parentObjectList) return;

                                if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                    expandCustomerSidebar();
                                }

                                const isOpen = subNav.classList.contains('show') || subNav.style.display === 'block';

                                document.querySelectorAll('.sub-nav').forEach(function (el) {
                                    el.classList.remove('show');
                                    el.style.display = 'none';
                                });

                                document.querySelectorAll('.project-link').forEach(function (el) {
                                    el.classList.remove('active');
                                });

                                if (!isOpen) {
                                    parentObjectList.classList.add('show');
                                    parentObjectList.style.display = 'block';

                                    subNav.classList.add('show');
                                    subNav.style.display = 'block';

                                    clicked.classList.add('active');

                                    const customerId = clicked.dataset.objectCustomerId;
                                    const alternativeId = clicked.dataset.objectAlternativeId;
                                    const uniqueProductId = clicked.dataset.plId || clicked.dataset.objectProduct;
                                    const genericProductId = clicked.dataset.objectProduct;
                                    const noteList = document.getElementById('note-list');

                                    if (noteList && customerId && alternativeId && uniqueProductId) {
                                        noteList.innerHTML = '<div class="text-muted p-3">Lade Notizen...</div>';

                                        fetch(`/customer-notes/context/${customerId}/${alternativeId}/${genericProductId || 0}/${uniqueProductId || ''}`)
                                            .then(function (res) {
                                                if (!res.ok) throw new Error('Bad response');
                                                return res.text();
                                            })
                                            .then(function (html) {
                                                noteList.innerHTML = html;

                                                noteList.dataset.customerId = customerId;
                                                noteList.dataset.alternativeId = alternativeId;
                                                noteList.dataset.uniqueId = uniqueProductId;
                                                noteList.dataset.genericId = genericProductId;
                                                noteList.dataset.productId = genericProductId;
                                                noteList.dataset.noteType = 'product';

                                                refreshIcons();

                                                if (typeof initNoteListeners === 'function') {
                                                    initNoteListeners();
                                                }
                                            })
                                            .catch(function () {
                                                noteList.innerHTML = '<div class="text-danger p-3">Fehler beim Laden.</div>';
                                            });
                                    }
                                }

                                refreshIcons();
                            };

                            document.querySelectorAll('.project-link[data-product-key]').forEach(function (link) {
                                link.addEventListener('click', function (event) {
                                    event.preventDefault();
                                    event.stopPropagation();

                                    window.toggleProduct(this.dataset.productKey);
                                });
                            });

                            window.addEventListener('resize', function () {
                                autoSidebarMode();

                                if (window.innerWidth < 992) {
                                    rightPanel.classList.add('right-hidden');
                                    layout.classList.add('notes-hidden-mode');

                                    if (noteShowBtn) {
                                        noteShowBtn.classList.remove('d-none');
                                    }
                                }
                            });

                            document.addEventListener('keydown', function (event) {
                                if (event.key === 'Escape') {
                                    resetFullscreenModes();
                                }
                            });

                            closeSidebarLists();
                            autoSidebarMode();
                            refreshIcons();
                            });
                            </script>

                             <!-- Maximize Toggle Buttons  -->
                            <script>
                            function loadSectionPartial(customer_id, alternative_id, product_id, section) {
                                const url = `/customer/partial/${customer_id}/${alternative_id}/${product_id}/${section}`;

                                fetch(url)
                                    .then(response => {
                                        if (!response.ok) throw new Error('Fehler beim Laden des Abschnitts');
                                        return response.text();
                                    })
                                    .then(html => {
                                        document.getElementById('mainContent').innerHTML = html;

                                        // Optional: load extra sub-sections (partial wrappers)
                                    })
                                    .catch(error => {
                                        document.getElementById('mainContent').innerHTML =
                                            `<div class="alert alert-danger">${error.message}</div>`;
                                    });
                            }

                            </script>

                            


                        <script id="wizard-object-script">
                            (() => {
                                'use strict';

                                // =========================================================
                                // 1. KONFIGURATION
                                // =========================================================

                                const MAX_STEP = 6;

                                // 1 = Übersicht, 2 = Objektdaten, 3 = Dach, 4 = Heizung, 5 = E-Mobilität, 6 = Energie
                                const PRODUCT_TAB_MAP = {
                                    '17': [1, 2, 3, 6], // Photovoltaik
                                    '16': [1, 2, 4, 6], // Wärmepumpe
                                    '18': [1, 2, 5, 6], // Wallbox
                                    '31': [1, 2, 6],    // Batteriespeicher
                                    'default': [1, 2, 3, 4, 5, 6]
                                };

                                const SECTION_STEP_MAP = {
                                    object_data: 2,
                                    roof_info: 3,
                                    heating_info: 4,
                                    e_mobility: 5,
                                    energy_usage: 6
                                };

                                const FIELD_LABEL_MAP = {
                                    object_type: 'Objektart',
                                    building_condition: 'Zustand',
                                    usage_type: 'Nutzungsart',
                                    heated_area: 'Wohnfläche',
                                    number_we: 'Wohneinheiten',
                                    story_count: 'Geschosse',
                                    person_count: 'Personen',
                                    owner_count: 'Details zum Eigentümer',
                                    building_year: 'Baujahr',
                                    masonry: 'Mauerwerk',
                                    external_insulation_thickness: 'Dämmung',
                                    window_glazing: 'Fenster Verglasung',
                                    window_frame: 'Fenster Rahmen',
                                    window_year: 'Fenster Bj.',
                                    door_year: 'Tür Bj.',
                                    door_condition: 'Tür Zustand',
                                    object_remark: 'Bemerkung',

                                    heating_system_type: 'Technologie',
                                    heating_type: 'Wärmeübergabe',
                                    heating_load_calculation: 'Heizlast (kW)',
                                    heating_system_age: 'Alter (Jahre)',
                                    heating_circuits_count: 'Heizkreise',
                                    pipe_system_material: 'Rohrmaterial',
                                    pipe_system_count: 'Rohranzahl',
                                    chimney: 'Kamin',
                                    total_heat_consumption: 'Wärmebedarf p.a.',
                                    total_electricity_consumption: 'Strombedarf p.a.',
                                    consumption: 'Verbrauch',
                                    quantity: 'Menge',
                                    wood_consumption: 'Holz p.a.',
                                    hot_water_generation: 'Warmwasser',
                                    solar_thermal: 'Solarthermie',
                                    bathroom_count: 'Bäderanzahl',
                                    bathtub_count: 'Badewannen',
                                    installation_location: 'Aufstellungsort',
                                    installation_location_extra: 'Aufstellungsort Sonstiges',
                                    income_level: 'Einkommen',
                                    heating_remark: 'Bemerkung',

                                    electric_car: 'Elektroauto',
                                    electric_car_count: 'Anzahl Autos',
                                    car_kilo: 'Fahrleistung (p.a.)',
                                    company_vehicle: 'Firmenfahrzeug',
                                    bidirectional_car: 'Bidirektionales Laden',
                                    wallbox_count: 'Wallboxen',
                                    wallbox_location: 'Montageort',
                                    heavy_current_cable: 'Starkstromkabel',
                                    network_cable: 'Netzwerk / LAN',
                                    groundwork: 'Erdarbeiten',
                                    car_remark: 'Bemerkung',

                                    power_household: 'Haushaltsstrom (kWh)',
                                    power_heatpump: 'WP-Strom (kWh)',
                                    power_electric_car: 'E-Auto-Strom (kWh)',
                                    power_other: 'Sonstiges (kWh)',
                                    power_total: 'Gesamtverbrauch',
                                    meter_cabinet: 'Zählerschrank',
                                    meter_count: 'Anzahl Zähler',
                                    tenant_model: 'Mieterstrommodell',
                                    installation_location_power: 'Aufstellungsort (Technik)',
                                    network_wlan: 'Netzwerk / WLAN',
                                    energy_remark: 'Bemerkung'
                                };

                                const ROOF_FIELD_LABEL_MAP = {
                                    designation: 'Name der Fläche',
                                    type: 'Dachform',
                                    roof_type: 'Dachtyp',
                                    roof_orientation: 'Ausrichtung',
                                    roof_pitch: 'Neigung',
                                    roof_height: 'Traufhöhe (in Metern)',
                                    roof_covering_name: 'Eindeckung',
                                    roof_covering_company: 'Hersteller',
                                    roof_covering_model: 'Model',
                                    roof_age: 'Alter (Jahre)',
                                    roof_renovation: 'Sanierung nötig?',
                                    pv_existing: 'PV vorhanden?',
                                    kwp_size: 'Größe (kWp)',
                                    intention: 'Weiteres Vorgehen',
                                    notes: 'Bemerkungen zur Dachfläche'
                                };

                                // =========================================================
                                // 2. HILFSFUNKTIONEN
                                // =========================================================

                                function refreshFeather() {
                                    if (typeof feather !== 'undefined') {
                                        feather.replace();
                                    }
                                }

                                function getStepButton(stepId) {
                                    return document.getElementById(`nav-${stepId}`);
                                }

                                function getStepContent(stepId) {
                                    return document.getElementById(`step-${stepId}`);
                                }

                                function getCurrentStepId() {
                                    const activeBtn = document.querySelector('.tab-btn.active');
                                    if (!activeBtn || !activeBtn.id) return 1;
                                    const match = activeBtn.id.match(/^nav-(\d+)$/);
                                    return match ? parseInt(match[1], 10) : 1;
                                }

                                function normalizeNumberString(value) {
                                    if (value === undefined || value === null) return 0;
                                    const parsed = parseFloat(String(value).trim().replace(',', '.'));
                                    return isNaN(parsed) || parsed < 0 ? 0 : parsed;
                                }

                                function getGermanFieldLabel(field) {
                                    if (!field) return 'Feld';

                                    const formGroup = field.closest('.form-group');
                                    if (formGroup) {
                                        const label = formGroup.querySelector('label.form-label');
                                        if (label) {
                                            const cloned = label.cloneNode(true);
                                            cloned.querySelectorAll('small, i').forEach(el => el.remove());
                                            const text = (cloned.textContent || '').trim();
                                            if (text) return text;
                                        }
                                    }

                                    if (field.id) {
                                        const explicitLabel = document.querySelector(`label[for="${field.id}"]`);
                                        if (explicitLabel) {
                                            const cloned = explicitLabel.cloneNode(true);
                                            cloned.querySelectorAll('small, i').forEach(el => el.remove());
                                            const text = (cloned.textContent || '').trim();
                                            if (text) return text;
                                        }
                                    }

                                    const rawName = field.name || field.id || 'Feld';
                                    const roofMatch = rawName.match(/^roofs\[\d+\]\[(.+)\]$/);
                                    if (roofMatch) {
                                        return ROOF_FIELD_LABEL_MAP[roofMatch[1]] || roofMatch[1];
                                    }

                                    return FIELD_LABEL_MAP[rawName] || rawName;
                                }

                                function findFieldByNameOrId(nameOrId) {
                                    try {
                                        return document.getElementById(nameOrId) || document.querySelector(`[name="${CSS.escape(nameOrId)}"]`);
                                    } catch (e) {
                                        return document.getElementById(nameOrId) || document.querySelector(`[name="${nameOrId}"]`);
                                    }
                                }

                                function showStepContent(stepId) {
                                    document.querySelectorAll('.step-content-box').forEach(el => el.classList.add('hidden'));
                                    const target = getStepContent(stepId);
                                    if (target) target.classList.remove('hidden');
                                }

                                function setActiveTab(stepId) {
                                    document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
                                    const targetBtn = getStepButton(stepId);
                                    if (targetBtn && !targetBtn.classList.contains('hidden')) {
                                        targetBtn.classList.add('active');
                                    }
                                }

                                function scrollStepWrapperToTop() {
                                    const wrapper = document.querySelector('.step-wrapper');
                                    if (wrapper) wrapper.scrollTop = 0;
                                }

                                function getNextVisibleStep(currentStep) {
                                    for (let i = currentStep + 1; i <= MAX_STEP; i++) {
                                        const btn = getStepButton(i);
                                        if (btn && !btn.classList.contains('hidden')) return i;
                                    }
                                    return null;
                                }

                                function getPrevVisibleStep(currentStep) {
                                    for (let i = currentStep - 1; i >= 1; i--) {
                                        const btn = getStepButton(i);
                                        if (btn && !btn.classList.contains('hidden')) return i;
                                    }
                                    return null;
                                }

                                function isFieldFilled(field) {
                                    if (!field) return false;

                                    if (field.type === 'checkbox' || field.type === 'radio') {
                                        return !!field.checked;
                                    }

                                    return !!(field.value && String(field.value).trim() !== '');
                                }

                                function toggleMissingSidebarIfMobile() {
                                    const sidebar = document.getElementById('missingDataSidebar');
                                    if (!sidebar) return;

                                    if (window.innerWidth <= 768 && sidebar.classList.contains('is-open')) {
                                        sidebar.classList.remove('is-open');
                                    }
                                }

                                function getSelectedProductIds(input) {
                                    if (!input) return [];

                                    if (Array.isArray(input)) {
                                        return input.map(v => String(v).trim()).filter(Boolean);
                                    }

                                    if (typeof input === 'string') {
                                        const trimmed = input.trim();
                                        if (!trimmed) return [];

                                        try {
                                            const parsed = JSON.parse(trimmed);
                                            if (Array.isArray(parsed)) {
                                                return parsed.map(v => String(v).trim()).filter(Boolean);
                                            }
                                        } catch (e) { }

                                        if (trimmed.includes(',')) {
                                            return trimmed.split(',').map(v => String(v).trim()).filter(Boolean);
                                        }

                                        return [trimmed];
                                    }

                                    if (input instanceof HTMLSelectElement) {
                                        if (input.multiple) {
                                            return Array.from(input.selectedOptions).map(opt => String(opt.value).trim()).filter(Boolean);
                                        }
                                        return input.value ? [String(input.value).trim()] : [];
                                    }

                                    if (typeof input === 'object' && input.value !== undefined) {
                                        return input.value ? [String(input.value).trim()] : [];
                                    }

                                    return [String(input).trim()].filter(Boolean);
                                }

                                function getAllowedTabsForProducts(productIds) {
                                    const ids = getSelectedProductIds(productIds);

                                    if (!ids.length) {
                                        return [...PRODUCT_TAB_MAP.default];
                                    }

                                    const merged = new Set();

                                    ids.forEach(productId => {
                                        const tabs = PRODUCT_TAB_MAP[String(productId)] || PRODUCT_TAB_MAP.default;
                                        tabs.forEach(step => merged.add(step));
                                    });

                                    return Array.from(merged).sort((a, b) => a - b);
                                }

                                function detectSelectedProductsFromDOM() {
                                    const productSelect = document.querySelector('.product-select');
                                    if (productSelect) {
                                        return getSelectedProductIds(productSelect);
                                    }

                                    const checkedProducts = Array.from(document.querySelectorAll('.product-select-checkbox:checked, input[name="product_id[]"]:checked, input[name="product_ids[]"]:checked'));
                                    if (checkedProducts.length) {
                                        return checkedProducts.map(el => String(el.value).trim()).filter(Boolean);
                                    }

                                    return [];
                                }

                                // =========================================================
                                // 3. SMART TABS
                                // =========================================================

                                function applySmartTabs(productInput) {
                                    const allowedTabs = getAllowedTabsForProducts(productInput);

                                    document.querySelectorAll('.tab-btn').forEach((btn, index) => {
                                        const stepNum = index + 1;

                                        if (allowedTabs.includes(stepNum)) {
                                            btn.classList.remove('hidden');
                                        } else {
                                            btn.classList.add('hidden');
                                        }
                                    });

                                    const currentStep = getCurrentStepId();
                                    if (!allowedTabs.includes(currentStep)) {
                                        window.goToStep(1);
                                    } else {
                                        window.goToStep(currentStep);
                                    }

                                    setTimeout(window.updateProgressCounts, 100);
                                }

                                // =========================================================
                                // 4. NAVIGATION
                                // =========================================================

                                window.goToStep = function (stepId) {
                                    const numericStep = parseInt(stepId, 10);
                                    if (isNaN(numericStep) || numericStep < 1 || numericStep > MAX_STEP) return;

                                    const btn = getStepButton(numericStep);
                                    if (btn && btn.classList.contains('hidden')) return;

                                    showStepContent(numericStep);
                                    setActiveTab(numericStep);
                                    scrollStepWrapperToTop();
                                    refreshFeather();
                                    window.updateProgressCounts();
                                };

                                window.goNext = function () {
                                    const currentStep = getCurrentStepId();
                                    const nextStep = getNextVisibleStep(currentStep);
                                    if (nextStep) window.goToStep(nextStep);
                                };

                                window.goPrev = function () {
                                    const currentStep = getCurrentStepId();
                                    const prevStep = getPrevVisibleStep(currentStep);
                                    if (prevStep) window.goToStep(prevStep);
                                };

                                window.toggleMissingSidebar = function () {
                                    const sidebar = document.getElementById('missingDataSidebar');
                                    if (sidebar) sidebar.classList.toggle('is-open');
                                };

                                window.focusField = function (nameOrId) {
                                    setTimeout(() => {
                                        const field = findFieldByNameOrId(nameOrId);
                                        if (!field) return;

                                        field.focus();
                                        field.scrollIntoView({ behavior: 'smooth', block: 'center' });

                                        const originalBackground = field.style.backgroundColor;
                                        const originalTransition = field.style.transition;

                                        field.style.transition = 'background-color 0.25s ease';
                                        field.style.backgroundColor = '#fef08a';

                                        setTimeout(() => {
                                            field.style.backgroundColor = originalBackground;
                                            field.style.transition = originalTransition;
                                        }, 1200);
                                    }, 300);
                                };

                                // =========================================================
                                // 5. FEHLENDE DATEN + FORTSCHRITT
                                // =========================================================

                                window.updateProgressCounts = function () {
                                    const missingDataList = document.getElementById('missingDataList');
                                    const toggleBtn = document.getElementById('toggleMissingBtn');

                                    let missingHtml = '';
                                    let totalMissingAcrossWizard = 0;

                                    document.querySelectorAll('form.partial-form').forEach(form => {
                                        const section = form.dataset.section;
                                        const stepNum = SECTION_STEP_MAP[section];
                                        const tabBtn = getStepButton(stepNum);

                                        if (!stepNum || !tabBtn || tabBtn.classList.contains('hidden')) return;

                                        const counterEl = document.getElementById(`step${stepNum}-count`);
                                        const progressBar = document.getElementById(`step${stepNum}-progress`);
                                        const contentBox = form.closest('.step-content-box');

                                        const wasHidden = contentBox && contentBox.classList.contains('hidden');
                                        if (wasHidden) contentBox.classList.remove('hidden');

                                        const fields = form.querySelectorAll('input:not([type="hidden"]), select, textarea');
                                        let total = 0;
                                        let filled = 0;
                                        const missingFieldsInSection = [];

                                        fields.forEach(field => {
                                            if (field.name === '_token') return;

                                            total++;

                                            if (isFieldFilled(field)) {
                                                filled++;
                                            } else {
                                                missingFieldsInSection.push({
                                                    name: getGermanFieldLabel(field),
                                                    elementId: field.id || field.name || ''
                                                });
                                            }
                                        });

                                        if (wasHidden) contentBox.classList.add('hidden');

                                        if (total > 0) {
                                            const percent = (filled / total) * 100;
                                            if (counterEl) counterEl.textContent = `${filled}/${total}`;
                                            if (progressBar) progressBar.style.width = `${percent}%`;
                                        }

                                        if (missingFieldsInSection.length > 0) {
                                            totalMissingAcrossWizard += missingFieldsInSection.length;

                                            const tabLabelEl = tabBtn.querySelector('.tab-label');
                                            const tabLabel = tabLabelEl ? tabLabelEl.textContent.trim() : section;
                                            const groupId = `missing-group-${stepNum}`;

                                            const missingItemsHtml = missingFieldsInSection.map(field => `
                                                    <div class="missing-item" onclick="goToStep(${stepNum}); focusField('${String(field.elementId).replace(/'/g, "\\'")}'); toggleMissingSidebarIfMobile();">
                                                        <span class="missing-item-icon">
                                                            <i class="feather icon-chevron-right"></i>
                                                        </span>
                                                        <span>${field.name}</span>
                                                    </div>
                                                `).join('');

                                            missingHtml += `
                                                    <div class="missing-group-card is-collapsed" id="${groupId}">
                                                        <div class="missing-group-head" onclick="toggleMissingGroup('${groupId}')">
                                                            <div class="missing-group-left">
                                                                <div class="missing-group-title">
                                                                    <i class="feather icon-folder"></i>
                                                                    ${tabLabel}
                                                                </div>
                                                                <div class="missing-group-meta">Karte aufklappen oder direkt den Tab öffnen</div>
                                                            </div>

                                                            <div class="missing-group-actions">
                                                                <span class="missing-badge">${missingFieldsInSection.length}</span>

                                                                <button
                                                                    type="button"
                                                                    class="missing-open-tab"
                                                                    onclick="event.stopPropagation(); goToStep(${stepNum}); toggleMissingSidebarIfMobile();"
                                                                >
                                                                    Öffnen
                                                                </button>

                                                                <span class="missing-collapse-icon" onclick="event.stopPropagation(); toggleMissingGroup('${groupId}')">
                                                                    <i class="feather icon-chevron-down"></i>
                                                                </span>
                                                            </div>
                                                        </div>

                                                        <div class="missing-items">
                                                            ${missingItemsHtml}
                                                        </div>
                                                    </div>
                                                `;
                                        }
                                    });

                                    if (missingDataList) {
                                        missingDataList.innerHTML = missingHtml || `
                                                <div class="missing-empty">
                                                    <i class="feather icon-check-circle"></i>
                                                    Alles komplett!
                                                </div>
                                            `;
                                    }

                                    if (toggleBtn) {
                                        toggleBtn.innerHTML = `
                                                <i class="feather icon-check-square"></i>
                                                Fehlendes (${totalMissingAcrossWizard})
                                            `;

                                        toggleBtn.classList.remove('is-success');
                                        if (totalMissingAcrossWizard === 0) {
                                            toggleBtn.classList.add('is-success');
                                        }
                                    }

                                    refreshFeather();
                                };

                                window.toggleMissingSidebarIfMobile = toggleMissingSidebarIfMobile;

                                // =========================================================
                                // 6. UI TOGGLES
                                // =========================================================

                                window.toggleRoofCard = function (headerElement) {
                                    const card = headerElement.closest('.fw-roof-card') || headerElement.closest('.roof-card') || headerElement.closest('.roof-group');
                                    const body = headerElement.nextElementSibling || (card ? card.querySelector('.fw-roof-body, .roof-body') : null);
                                    const icon = headerElement.querySelector('.toggle-icon');

                                    if (!body) return;

                                    const isHidden = body.style.display === 'none' || body.classList.contains('hidden');

                                    if (isHidden) {
                                        body.style.display = 'block';
                                        body.classList.remove('hidden');
                                        if (icon) icon.style.transform = 'rotate(0deg)';
                                        if (card) card.classList.remove('is-collapsed');
                                    } else {
                                        body.style.display = 'none';
                                        body.classList.add('hidden');
                                        if (icon) icon.style.transform = 'rotate(-90deg)';
                                        if (card) card.classList.add('is-collapsed');
                                    }
                                };

                                window.toggleMissingGroup = function (groupId) {
                                    const card = document.getElementById(groupId);
                                    if (!card) return;
                                    card.classList.toggle('is-collapsed');
                                };

                                function setupElectricCarToggle(root = document) {
                                    const electricCarSelect =
                                        root.querySelector('#electric_car_select') ||
                                        root.querySelector('#electric_car') ||
                                        root.querySelector('[name="electric_car"]');

                                    const electricCarCountGroup = root.querySelector('#electric_car_count_group');
                                    if (!electricCarSelect || !electricCarCountGroup) return;

                                    const updateVisibility = () => {
                                        if (electricCarSelect.value === 'Ja' || electricCarSelect.value === 'Geplant') {
                                            electricCarCountGroup.style.display = 'flex';
                                            electricCarCountGroup.style.flexDirection = 'column';
                                        } else {
                                            electricCarCountGroup.style.display = 'none';
                                        }
                                    };

                                    electricCarSelect.addEventListener('change', updateVisibility);
                                    updateVisibility();
                                }

                                // =========================================================
                                // 7. POWER CALCULATOR
                                // =========================================================

                                function initPowerCalculatorWithIDs(context = document) {
                                    const $context = $(context);
                                    const $household = $context.find('#power_household_input');
                                    const $heatpump = $context.find('#power_heatpump_input');
                                    const $electricCar = $context.find('#power_electric_car_input');
                                    const $other = $context.find('#power_other_input');
                                    const $total = $context.find('#power_total');
                                    const $totalHidden = $context.find('#power_total_hidden');

                                    function updateTotal() {
                                        if (!$total.length && !$totalHidden.length) return;

                                        const totalValue =
                                            normalizeNumberString($household.val()) +
                                            normalizeNumberString($heatpump.val()) +
                                            normalizeNumberString($electricCar.val()) +
                                            normalizeNumberString($other.val());

                                        if ($total.length) {
                                            $total.val(totalValue.toFixed(2).replace('.', ','));
                                        }

                                        if ($totalHidden.length) {
                                            $totalHidden.val(totalValue.toFixed(2));
                                        }

                                        let $year = $context.find('#power_total_year');
                                        if (!$year.length && $total.length) {
                                            $year = $('<small id="power_total_year" style="color: var(--slate-400); margin-top: 0.25rem;"></small>');
                                            $year.insertAfter($total);
                                        }

                                        if ($year.length) {
                                            $year.text('≈ ' + (totalValue * 365).toLocaleString('de-DE') + ' kWh / Jahr');
                                        }
                                    }

                                    const $inputs = $household.add($heatpump).add($electricCar).add($other);
                                    if ($inputs.length) {
                                        $inputs.off('input.powercalc').on('input.powercalc', updateTotal);
                                        updateTotal();
                                    }
                                }

                                window.initPowerCalculatorWithIDs = initPowerCalculatorWithIDs;

                                // =========================================================
                                // 8. AJAX CONTENT LOAD
                                // =========================================================

                                window.loadFullAlternativeObject = function (button) {
                                    const customerId = button.dataset.customerId;
                                    const alternativeId = button.dataset.alternativeId;
                                    const productIds = button.dataset.productIds || button.dataset.productId || '';
                                    const mainContent = document.getElementById('mainContent');

                                    if (!mainContent) return;

                                    const url = `/customer/alternative/partials/${customerId}/${alternativeId}/${button.dataset.productId}/objekt`;

                                    mainContent.innerHTML = `
                                            <div class="text-center py-4">
                                                <span class="spinner-border spinner-border-sm"></span>
                                                Lade Objektdaten...
                                            </div>
                                        `;

                                    fetch(url)
                                        .then(response => {
                                            if (!response.ok) {
                                                throw new Error('Fehler beim Laden des Objekts');
                                            }
                                            return response.text();
                                        })
                                        .then(html => {
                                            mainContent.innerHTML = html;

                                            refreshFeather();
                                            initPowerCalculatorWithIDs(mainContent);
                                            setupElectricCarToggle(mainContent);

                                            const detectedProducts = productIds ? getSelectedProductIds(productIds) : detectSelectedProductsFromDOM();
                                            applySmartTabs(detectedProducts);

                                            setTimeout(window.updateProgressCounts, 200);
                                        })
                                        .catch(error => {
                                            mainContent.innerHTML = `<div class="alert alert-danger m-3">${error.message}</div>`;
                                            console.error('Fehler beim Laden:', error);
                                        });
                                };

                                // =========================================================
                                // 9. AJAX FORM SAVE
                                // =========================================================

                                function handlePartialFormSubmit(event) {
                                    const form = event.target;
                                    if (!form.classList.contains('partial-form')) return;

                                    event.preventDefault();

                                    const section = form.dataset.section;
                                    const id = form.dataset.id;
                                    const csrfInput = form.querySelector('input[name="_token"]');

                                    if (!csrfInput) {
                                        console.error('CSRF-Token fehlt.');
                                        return;
                                    }

                                    const formData = new FormData(form);
                                    formData.append('id', id);

                                    fetch('/new_lead_profile/alternative/object/save', {
                                        method: 'POST',
                                        headers: {
                                            'X-CSRF-TOKEN': csrfInput.value
                                        },
                                        body: formData
                                    })
                                        .then(response => {
                                            if (!response.ok) {
                                                throw new Error('Fehler beim Speichern von ' + section);
                                            }
                                            return response.json();
                                        })
                                        .then(() => {
                                            if (typeof Swal !== 'undefined') {
                                                Swal.fire({
                                                    icon: 'success',
                                                    title: 'Gespeichert',
                                                    text: `Abschnitt "${section}" erfolgreich gespeichert.`
                                                });
                                            }
                                            window.updateProgressCounts();
                                        })
                                        .catch(error => {
                                            if (typeof Swal !== 'undefined') {
                                                Swal.fire({
                                                    icon: 'error',
                                                    title: 'Fehler',
                                                    text: error.message
                                                });
                                            } else {
                                                alert(error.message);
                                            }
                                        });
                                }

                                // =========================================================
                                // 10. EVENTS
                                // =========================================================

                                $(document).on('change', '.product-select', function () {
                                    applySmartTabs(this);
                                });

                                $(document).on('change', '.product-select-checkbox, input[name="product_id[]"], input[name="product_ids[]"]', function () {
                                    const selectedProducts = detectSelectedProductsFromDOM();
                                    applySmartTabs(selectedProducts);
                                });

                                document.body.addEventListener('submit', handlePartialFormSubmit);

                                $(document).on('input change', 'form.partial-form input, form.partial-form select, form.partial-form textarea', function () {
                                    window.updateProgressCounts();
                                });

                                // =========================================================
                                // 11. INIT
                                // =========================================================

                                function initWizard() {
                                    setupElectricCarToggle(document);
                                    initPowerCalculatorWithIDs(document);

                                    const selectedProducts = detectSelectedProductsFromDOM();
                                    if (selectedProducts.length) {
                                        applySmartTabs(selectedProducts);
                                    } else {
                                        applySmartTabs(PRODUCT_TAB_MAP.default);
                                    }

                                    setTimeout(window.updateProgressCounts, 300);
                                    refreshFeather();
                                }

                                document.addEventListener('DOMContentLoaded', initWizard);
                            })();
                        </script>

                        <script id="84723">
                            window.toggleMissingGroup = function (groupId) {
                                const card = document.getElementById(groupId);
                                if (!card) return;
                                card.classList.toggle('is-collapsed');
                            };
                        </script>
