                                    .product-card-main > img.rounded-circle {
                                        width: 24px !important;
                                        height: 24px !important;
                                        margin-left: -8px !important;
                                        border: 2px solid #ffffff !important;
                                        box-shadow: 0 4px 10px rgba(15, 23, 42, .16);
                                        background: #ffffff;
                                        flex: 0 0 auto;
