                                    .product-meta div {
                                        overflow: hidden;
                                        text-overflow: ellipsis;
                                        white-space: nowrap;
                                    }

                                    .product-card-actions {
                                        display: flex;
                                        gap: 5px;
                                        align-items: center;
                                        margin-top: 0 !important;
                                        flex-shrink: 0;
