                                    .product-version-label {
                                        margin-top: 6px;
                                    }

                                    .product-version-label span {
                                        display: inline-flex;
                                        align-items: center;
                                        border-radius: 999px;
                                        padding: 3px 8px;
                                        font-size: 10px;
                                        font-weight: 900;
                                        background: #c0d8ea;
