    <script id="customer-profile-workflow-addon-script">
    (function () {
        'use strict';

        window.APP = window.APP || {};
        window.APP.stageWorkflow = window.APP.stageWorkflow || {
            mode: 'company',
            productId: null,
            productStages: [],
            productStageNames: {},
            productStageMeta: {}
        };
        window.APP.endpoints = Object.assign(window.APP.endpoints || {}, {
            stageWorkflowConfig: "{{ route('customer.profile.workflow.stages') }}",
            stageWorkflowMove: function (leadProductId) {
                return "{{ url('/customer-profile/lead-products') }}/" + leadProductId + "/move-stage";
            },
            stageWorkflowMoveForward: function (leadProductId) {
                return "{{ url('/customer-profile/lead-products') }}/" + leadProductId + "/move-product-stage-forward";
            }
        });


        const csrf = () => document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';
        const esc = (v) => String(v ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');

        const employeeBase = (typeof window.EMPLOYEE_IMAGE !== 'undefined' && window.EMPLOYEE_IMAGE)
            ? String(window.EMPLOYEE_IMAGE).replace(/\/+$/, '')
            : ((typeof EMPLOYEE_IMAGE_BASE !== 'undefined' && EMPLOYEE_IMAGE_BASE) ? String(EMPLOYEE_IMAGE_BASE).replace(/\/+$/, '') : '/images/employee');

        const defaultAvatar = (typeof window.GENDER !== 'undefined' && window.GENDER)
            ? window.GENDER
            : ((typeof GENDER_IMAGE !== 'undefined' && GENDER_IMAGE) ? GENDER_IMAGE : '/images/gender/male.png');

        const empImg = (img) => {
            if (!img) return defaultAvatar;
            if (/^https?:\/\//i.test(String(img))) return img;
            return `${employeeBase}/${String(img).replace(/^\/+/, '')}`;
        };

        const employeeList = () => {
            let raw = [];

            if (Array.isArray(window.ALL_EMPLOYEES) && window.ALL_EMPLOYEES.length) {
                raw = window.ALL_EMPLOYEES;
            } else if (typeof ALL_EMPLOYEES !== 'undefined' && Array.isArray(ALL_EMPLOYEES) && ALL_EMPLOYEES.length) {
                raw = ALL_EMPLOYEES;
            } else if (Array.isArray(window.employeeOptions) && window.employeeOptions.length) {
                raw = window.employeeOptions;
            } else {
                document.querySelectorAll('#employee option, select[name="employee_id[]"] option, select[name="employees[]"] option').forEach((opt) => {
                    if (!opt.value) return;
                    raw.push({
                        id: opt.value,
                        name: opt.dataset.name || opt.textContent || opt.value,
                        lastname: '',
                        image: opt.dataset.image || '',
                    });
                });
            }

            const seen = new Set();
            return raw.map((e) => {
                const id = Number(e.id || e.employee_id || e.emp_id || e.value || 0);
                const first = e.name || e.firstname || '';
                const last = e.lastname || e.last_name || '';
                return {
                    id,
                    name: `${last} ${first}`.trim() || `${first} ${last}`.trim() || e.text || `#${id}`,
                    image: e.image || e.employee_image || '',
                };
            }).filter(e => {
                if (e.id <= 0 || seen.has(String(e.id))) return false;
                seen.add(String(e.id));
                return true;
            });
        };

        const companyStages = () => {
            const raw = Array.isArray(window.COMPANY_STAGES) && window.COMPANY_STAGES.length
                ? window.COMPANY_STAGES
                : ((typeof COMPANY_STAGES !== 'undefined' && Array.isArray(COMPANY_STAGES) && COMPANY_STAGES.length)
                    ? COMPANY_STAGES
                    : ((typeof STAGE_FLOW !== 'undefined' && Array.isArray(STAGE_FLOW) && STAGE_FLOW.length)
                        ? STAGE_FLOW
                        : (Array.isArray(window.STAGE_FLOW) ? window.STAGE_FLOW : [])));

            const fallback = [
                { key: 'lead', name: 'Lead', label: 'Lead', color: '#93c21c', icon: 'user-plus', sort_order: 10 },
                { key: 'offer', name: 'Angebot', label: 'Angebot', color: '#93c21c', icon: 'file-text', sort_order: 20 },
                { key: 'deal', name: 'Auftrag', label: 'Auftrag', color: '#93c21c', icon: 'briefcase', sort_order: 30 },
                { key: 'project', name: 'Montage', label: 'Montage', color: '#93c21c', icon: 'tool', sort_order: 40 },
                { key: 'completed', name: 'Abschluss', label: 'Abschluss', color: '#93c21c', icon: 'flag', sort_order: 50 },
            ];

            return (raw.length ? raw : fallback)
                .map((s, idx) => ({
                    id: s.id || null,
                    key: s.key || s.stage || `stage_${idx}`,
                    name: s.name || s.label || s.stage || `Phase ${idx + 1}`,
                    color: s.color || '#93c21c',
                    icon: s.icon || 'circle',
                    sort_order: Number(s.sort_order ?? ((idx + 1) * 10)),
                    type: 'company',
                }))
                .sort((a, b) => a.sort_order - b.sort_order);
        };

        const normalizeStage = (stage) => {
            const key = String(stage || 'lead').toLowerCase();
            const map = {
                open: 'lead', new: 'lead', neu: 'lead', neue: 'lead',
                angebot: 'offer', verkauf: 'offer',
                nachfassen: 'follow_up', followup: 'follow_up',
                annehmen: 'accepted', angenommen: 'accepted',
                auftrag: 'deal', montage: 'project', projekt: 'project',
                abschluss: 'completed', complete: 'completed',
                archiv: 'archive', absage: 'junk', reject: 'junk', rejeck: 'junk',
            };
            return map[key] || key;
        };

        function getLeadProductId(productId, customerId, alternativeId) {
            const selector = [
                `.product-stage-step[data-product-id="${CSS.escape(String(productId))}"][data-customer-id="${CSS.escape(String(customerId))}"][data-alternative-id="${CSS.escape(String(alternativeId))}"]`,
                `.cpwf-team-btn[data-product-id="${CSS.escape(String(productId))}"][data-customer-id="${CSS.escape(String(customerId))}"][data-alternative-id="${CSS.escape(String(alternativeId))}"]`,
            ].join(',');
            const el = document.querySelector(selector);
            return el?.dataset?.leadProductId || el?.closest('.product-status-card')?.dataset?.leadProductId || '';
        }

        function getCardByContext(productId, customerId, alternativeId) {
            const step = document.querySelector(`.product-stage-step[data-product-id="${CSS.escape(String(productId))}"][data-customer-id="${CSS.escape(String(customerId))}"][data-alternative-id="${CSS.escape(String(alternativeId))}"]`);
            return step?.closest('.product-status-card') || step?.closest('.custom-responsive-card') || null;
        }

        function selectedEmployeeHtml(ids) {
            const map = new Map(employeeList().map(e => [String(e.id), e]));
            return ids.map((id) => {
                const e = map.get(String(id));
                if (!e) return '';
                return `<span class="cpwf-chip"><img src="${esc(empImg(e.image))}" alt="">${esc(e.name)}</span>`;
            }).join('');
        }

        function buildEmployeeOptions(selected = []) {
            const selectedSet = new Set((selected || []).map(String));
            return employeeList().map((e) => `
                <option value="${esc(e.id)}" ${selectedSet.has(String(e.id)) ? 'selected' : ''} data-image="${esc(empImg(e.image))}">
                    ${esc(e.name)}
                </option>
            `).join('');
        }

        function employeeMap() {
            return new Map(employeeList().map(e => [String(e.id), e]));
        }

        function decorateAssignments(assignments) {
            const map = employeeMap();
            return (Array.isArray(assignments) ? assignments : []).map((row) => {
                const employeeId = Number(row?.employee_id ?? row?.id ?? row?.emp_id ?? 0) || 0;
                const assignedBy = Number(row?.assigned_by ?? row?.changed_by ?? 0) || 0;
                return {
                    ...row,
                    employee_id: employeeId,
                    scope: row?.scope || 'company',
                    stage: row?.stage != null ? String(row.stage) : null,
                    old_stage: row?.old_stage != null ? String(row.old_stage) : null,
                    assigned_by: assignedBy || row?.assigned_by || null,
                    assigned_at: row?.assigned_at || row?.changed_at || null,
                    member: row?.member || map.get(String(employeeId)) || null,
                    assigned_by_user: row?.assigned_by_user || map.get(String(assignedBy)) || null,
                };
            }).filter(row => row.employee_id || row.member);
        }

        function parseJsonAttr(value, fallback = []) {
            try {
                const parsed = JSON.parse(value || '');
                return Array.isArray(parsed) ? parsed : fallback;
            } catch (e) {
                return fallback;
            }
        }

        function getScopeAssignments(scope) {
            const cardAssignments = parseJsonAttr(scope?.dataset?.teamAssignments, []);
            if (cardAssignments.length) return decorateAssignments(cardAssignments);

            const holder = scope?.querySelector?.('[data-team-assignments]');
            const holderAssignments = parseJsonAttr(holder?.dataset?.teamAssignments, []);
            return decorateAssignments(holderAssignments);
        }

        function getStageLabel(stage, scope = 'company') {
            if (scope === 'product') return `Produktphase ${stage || ''}`.trim();
            const key = normalizeStage(stage);
            const found = companyStages().find(s => normalizeStage(s.key) === key);
            return found?.name || found?.label || key;
        }

        function getCurrentTeamAssignments(scope, stageKey = null) {
            const stage = normalizeStage(stageKey || scope?.dataset?.stage || 'lead');
            return getScopeAssignments(scope).filter(row => {
                const rowScope = row.scope || 'company';
                const rowStage = normalizeStage(row.stage || '');
                return rowScope === 'company' && rowStage === stage;
            });
        }

        function memberName(emp, fallbackId = '') {
            return `${emp?.lastname || ''} ${emp?.name || ''}`.trim()
                || `${emp?.name || ''} ${emp?.lastname || ''}`.trim()
                || (fallbackId ? `Mitarbeiter #${fallbackId}` : 'Mitarbeiter');
        }

        function assignmentMemberHTML(row) {
            const emp = row.member || employeeMap().get(String(row.employee_id)) || {};
            const assigner = row.assigned_by_user || employeeMap().get(String(row.assigned_by)) || null;
            const name = memberName(emp, row.employee_id);
            const by = assigner ? memberName(assigner, row.assigned_by) : (row.assigned_by ? `Mitarbeiter #${row.assigned_by}` : '—');
            const at = row.assigned_at ? new Date(row.assigned_at.replace(' ', 'T')).toLocaleString('de-DE') : '—';
            return `<span class="cpwf-team-history-member">
                <img src="${esc(empImg(emp.image))}" alt="${esc(name)}" title="${esc(name)}">
                <span><strong>${esc(name)}</strong><small>von ${esc(by)} • ${esc(at)}</small></span>
            </span>`;
        }

        function renderTeamHistoryHTML(assignments, currentStage = 'lead') {
            const rows = decorateAssignments(assignments).filter(row => (row.scope || 'company') === 'company');
            const orderedStages = companyStages().filter(s => !['junk', 'archive', 'ticket'].includes(normalizeStage(s.key)));
            const byStage = new Map();
            rows.forEach(row => {
                const key = normalizeStage(row.stage || 'lead');
                if (!byStage.has(key)) byStage.set(key, []);
                byStage.get(key).push(row);
            });

            const visibleStages = orderedStages.length
                ? orderedStages
                : Array.from(byStage.keys()).map(key => ({ key, name: getStageLabel(key) }));

            return `<div class="cpwf-team-history-box">
                ${visibleStages.map(stage => {
                    const key = normalizeStage(stage.key || stage.stage || stage.name);
                    const members = byStage.get(key) || [];
                    const isCurrent = normalizeStage(currentStage) === key ? ' is-current' : '';
                    return `<div class="cpwf-team-history-stage${isCurrent}">
                        <div class="cpwf-team-history-title">${esc(stage.name || stage.label || getStageLabel(key))}</div>
                        <div class="cpwf-team-history-members">
                            ${members.length ? members.map(assignmentMemberHTML).join('') : `<span class="cpwf-team-history-empty">Kein Team gespeichert</span>`}
                        </div>
                    </div>`;
                }).join('')}
            </div>`;
        }

        function openTeamHistoryModal(scope) {
            const currentStage = normalizeStage(scope?.dataset?.stage || scope?.querySelector?.('.product-stage-step.is-active')?.dataset?.stage || 'lead');
            const html = renderTeamHistoryHTML(getScopeAssignments(scope), currentStage);
            Swal.fire({
                title: 'Teams nach Phase',
                html: `${html}<div class="cpwf-team-overview-actions"><button type="button" class="btn btn-sm btn-primary" id="cpwfOpenTeamEdit"><i class="feather icon-edit-2"></i> Team ändern</button></div>`,
                width: 820,
                confirmButtonText: 'Schließen',
                customClass: { container: 'cpwf-swal-front' },
                didOpen: () => {
                    if (window.feather?.replace) window.feather.replace();
                    document.getElementById('cpwfOpenTeamEdit')?.addEventListener('click', () => {
                        Swal.close();
                        openWorkflowModal({
                            productId: scope?.dataset?.productId,
                            customerId: scope?.dataset?.customerId,
                            alternativeId: scope?.dataset?.alternativeId,
                            selectedStage: currentStage,
                            mode: 'company',
                        });
                    });
                }
            });
        }


        document.addEventListener('click', function (event) {
            const teamButton = event.target.closest('[data-team-view="1"], .cpwf-team-btn');
            if (!teamButton) return;

            event.preventDefault();
            event.stopPropagation();

            const scope = teamButton.closest('.product-status-card')
                || teamButton.closest('.custom-responsive-card')
                || teamButton.closest('.house-block')
                || teamButton.closest('.card');

            if (scope) {
                openTeamHistoryModal(scope);
            }
        });

        function initSelect2Employees() {
            const select = document.getElementById('cpwfTeamSelect');
            if (!select) return;

            if (!select.options.length) {
                select.innerHTML = buildEmployeeOptions([]);
            }

            if (!window.jQuery || !window.jQuery.fn.select2) {
                select.classList.add('form-control');
                select.addEventListener('change', function () {
                    const ids = Array.from(this.selectedOptions || []).map(opt => opt.value).filter(Boolean);
                    const preview = document.getElementById('cpwfTeamPreview');
                    if (preview) preview.innerHTML = selectedEmployeeHtml(ids);
                });
                select.dispatchEvent(new Event('change'));
                return;
            }

            const $select = window.jQuery(select);
            if ($select.data('select2')) {
                $select.select2('destroy');
            }

            const $popup = window.jQuery(Swal.getPopup() || document.body);
            $select.select2({
                width: '100%',
                dropdownParent: $popup,
                placeholder: 'Team / Verantwortliche wählen',
                closeOnSelect: false,
                allowClear: true,
                templateResult: function (item) {
                    if (!item.id) return item.text;
                    const img = window.jQuery(item.element).data('image') || defaultAvatar;
                    return window.jQuery(`<span style="display:flex;align-items:center;gap:8px;min-height:28px;"><img src="${esc(img)}" style="width:24px;height:24px;border-radius:999px;object-fit:cover;"> <span>${esc(item.text)}</span></span>`);
                },
                templateSelection: function (item) {
                    return item.text;
                }
            }).on('change', function () {
                const ids = window.jQuery(this).val() || [];
                const preview = document.getElementById('cpwfTeamPreview');
                if (preview) preview.innerHTML = selectedEmployeeHtml(ids);
            }).trigger('change');
        }

        async function fetchFirstJson(urls) {
            for (const url of urls) {
                try {
                    const res = await fetch(url, { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' });
                    if (!res.ok) continue;
                    const json = await res.json();
                    if (json && (json.success || Array.isArray(json.stages) || Array.isArray(json))) return json;
                } catch (e) {}
            }
            return null;
        }

        async function loadProductStages(productId) {
            const pid = encodeURIComponent(productId);
            const json = await fetchFirstJson([
                `{{ route('customer.profile.workflow.stages') }}?mode=product&product_id=${pid}`,
                `/customer-profile/workflow/stages?mode=product&product_id=${pid}`,
                `/admin/kanban-stage-workflow/config?mode=product&product_id=${pid}`,
                `/kanban-stage-workflow/config?mode=product&product_id=${pid}`,
                `/lead-product/stage-workflow/config?mode=product&product_id=${pid}`,
                `/get-stages-by-product?product_id=${pid}`,
            ]);

            const raw = Array.isArray(json) ? json : (json?.stages || []);
            return raw.map((s, idx) => ({
                type: 'product',
                id: s.id || s.stage_id || null,
                key: s.key || `product_stage_${s.id || s.stage_id || idx}`,
                name: s.name || s.stage || s.label || `Produktphase ${idx + 1}`,
                color: s.color || '#93c21c',
                icon: s.icon || 'layers',
                sort_order: Number(s.sort_order ?? ((idx + 1) * 10)),
                phases: Array.isArray(s.phases) ? s.phases : [],
                product_id: s.product_id || productId,
            })).sort((a, b) => a.sort_order - b.sort_order);
        }

        function renderStageChoices(stages, selectedKey, mode) {
            return stages.map((s, idx) => {
                const key = mode === 'product' ? String(s.id || s.key || idx) : normalizeStage(s.key);
                const isSelected = String(key) === String(selectedKey || '');
                return `
                    <label class="cpwf-stage-option ${isSelected ? 'is-selected' : ''}" data-cpwf-stage-option>
                        <span class="cpwf-stage-icon" style="background:${esc(s.color || '#93c21c')}"><i class="feather icon-${esc(s.icon || 'circle')}"></i></span>
                        <span>
                            <strong>${esc(s.name)}</strong>
                            ${mode === 'product' && s.phases?.length ? `<br><small class="text-muted">${esc(s.phases.length)} Arbeitsschritte</small>` : ''}
                        </span>
                        <input type="radio" name="cpwfStageChoice" value="${esc(key)}" ${isSelected ? 'checked' : ''}
                            data-product-stage-id="${esc(s.id || '')}">
                    </label>
                `;
            }).join('');
        }

        function bindStageChoiceHighlight() {
            document.querySelectorAll('[data-cpwf-stage-option]').forEach((label) => {
                label.addEventListener('click', () => {
                    document.querySelectorAll('[data-cpwf-stage-option]').forEach(x => x.classList.remove('is-selected'));
                    label.classList.add('is-selected');
                });
            });
        }

        async function saveWorkflowMove({ leadProductId, customerId, alternativeId, productId, mode, selectedStage, productStageId, productTaskPhaseId, reason, teams }) {
            const body = {
                mode,
                stage_mode: mode,
                stage: selectedStage,
                company_stage_key: mode === 'company' ? selectedStage : null,
                product_stage_id: mode === 'product' ? productStageId : null,
                product_task_phase_id: productTaskPhaseId || null,
                description: reason,
                reason,
                teams,
            };

            const workflowUrls = leadProductId ? [
                `{{ url('/customer-profile/lead-products') }}/${leadProductId}/move-stage`,
                `/customer-profile/lead-products/${leadProductId}/move-stage`,
                `/admin/kanban-stage-workflow/move/${leadProductId}`,
                `/kanban-stage-workflow/move/${leadProductId}`,
                `/lead-product/${leadProductId}/workflow/move`,
                `/lead-product-list/${leadProductId}/workflow/move`,
                `/lead-product-lists/${leadProductId}/workflow/move`,
                `/admin/kanban/lead-product/${leadProductId}/workflow/move`,
            ] : [];

            for (const url of workflowUrls) {
                try {
                    const res = await fetch(url, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf(), 'X-Requested-With': 'XMLHttpRequest' },
                        credentials: 'same-origin',
                        body: JSON.stringify(body),
                    });
                    if (!res.ok) continue;
                    return await res.json();
                } catch (e) {}
            }

            if (typeof window.postStageChange === 'function') {
                return window.postStageChange(customerId, alternativeId, productId, mode === 'company' ? selectedStage : selectedStage, reason);
            }

            const fallbackUrl = `/lead-product/change-stage/${customerId}/${alternativeId}/${productId}`;
            const res = await fetch(fallbackUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf(), 'X-Requested-With': 'XMLHttpRequest' },
                credentials: 'same-origin',
                body: JSON.stringify(body),
            });
            return await res.json();
        }

        async function openWorkflowModal({ productId, customerId, alternativeId, selectedStage = null, mode = 'company' }) {
            const leadProductId = getLeadProductId(productId, customerId, alternativeId);
            const company = companyStages();
            const productStages = await loadProductStages(productId);
            const modalMode = mode === 'product' ? 'product' : 'company';
            const stagesToShow = modalMode === 'product' ? productStages : company;

            if (modalMode === 'product' && !productStages.length) {
                Swal.fire({ icon: 'info', title: 'Keine Produktphasen', text: 'Für dieses Produkt wurden noch keine Produktphasen gefunden.', customClass: { container: 'cpwf-swal-front' } });
                return;
            }

            const selectedKey = modalMode === 'product'
                ? String((productStages.find(s => String(s.key) === String(selectedStage))?.id) || productStages[0]?.id || '')
                : normalizeStage(selectedStage || company[0]?.key || 'lead');

            const scope = getCardByContext(productId, customerId, alternativeId);
            const existingAssignments = getScopeAssignments(scope);
            const currentTeamIds = existingAssignments
                .filter(row => {
                    const rowScope = row.scope || 'company';
                    if (modalMode === 'product') return rowScope === 'product' && String(row.stage || '') === String(selectedKey);
                    return rowScope === 'company' && normalizeStage(row.stage || '') === normalizeStage(selectedKey);
                })
                .map(row => Number(row.employee_id))
                .filter(Boolean);

            const title = modalMode === 'product' ? 'Produktphase ändern' : 'Unternehmensphase ändern';
            const helpText = modalMode === 'product'
                ? 'Hier wird nur die Produktphase gespeichert. Unternehmens-Kanban bleibt unverändert.'
                : 'Hier wird die Unternehmensphase geändert. Zusätzlich siehst du die Produktphasen zur Orientierung.';

            const html = `
                <div class="cpwf-modal-grid">
                    <div class="cpwf-modal-card">
                        <div class="cpwf-modal-title">
                            <span><i class="feather icon-info"></i> Workflow</span>
                            <span class="badge badge-light">${modalMode === 'product' ? 'Produkt' : 'Unternehmen'}</span>
                        </div>
                        <div class="text-muted" style="font-size:12px;">${esc(helpText)}</div>
                        ${modalMode === 'company' && productStages.length ? `
                            <div class="cpwf-product-stage-box mt-2">
                                <strong>Produktphasen vorhanden:</strong><br>
                                ${productStages.map(s => esc(s.name)).join(' → ')}
                            </div>
                        ` : ''}
                    </div>

                    <div class="cpwf-modal-card">
                        <div class="cpwf-modal-title"><span><i class="feather icon-layers"></i> Zielphase</span></div>
                        <div class="cpwf-modal-stage-list">
                            ${renderStageChoices(stagesToShow, selectedKey, modalMode)}
                        </div>
                    </div>

                    <div class="cpwf-modal-card cpwf-team-select-wrap">
                        <div class="cpwf-modal-title"><span><i class="feather icon-users"></i> Team / Verantwortliche</span></div>
                        <select id="cpwfTeamSelect" multiple="multiple" style="width:100%;">
                            ${buildEmployeeOptions(currentTeamIds)}
                        </select>
                        <div id="cpwfTeamPreview" class="cpwf-team-preview"></div>
                    </div>

                    ${modalMode === 'company' ? `
                        <div class="cpwf-modal-card">
                            <div class="cpwf-modal-title"><span><i class="feather icon-list"></i> Bisherige Teams nach Unternehmensphase</span></div>
                            ${renderTeamHistoryHTML(existingAssignments, selectedKey)}
                        </div>
                    ` : ''}

                    <div class="cpwf-modal-card">
                        <div class="cpwf-modal-title"><span><i class="feather icon-message-square"></i> Grund / Notiz</span></div>
                        <textarea id="cpwfReason" class="form-control" rows="4" placeholder="Warum wird die Phase geändert?"></textarea>
                    </div>
                </div>
            `;

            const result = await Swal.fire({
                title,
                html,
                width: 820,
                showCancelButton: true,
                confirmButtonText: 'Speichern',
                cancelButtonText: 'Abbrechen',
                customClass: { container: 'cpwf-swal-front' },
                didOpen: () => {
                    initSelect2Employees();
                    bindStageChoiceHighlight();
                    if (window.feather?.replace) window.feather.replace();
                },
                preConfirm: () => {
                    const checked = document.querySelector('input[name="cpwfStageChoice"]:checked');
                    const reason = document.getElementById('cpwfReason')?.value || '';
                    const teams = window.jQuery ? (window.jQuery('#cpwfTeamSelect').val() || []) : [];
                    if (!checked) {
                        Swal.showValidationMessage('Bitte eine Phase wählen.');
                        return false;
                    }
                    return {
                        value: checked.value,
                        productStageId: checked.dataset.productStageId || null,
                        reason,
                        teams: teams.map(Number).filter(Boolean),
                    };
                },
            });

            if (!result.isConfirmed || !result.value) return;

            const payload = result.value;
            const selectedCompanyStage = modalMode === 'company' ? normalizeStage(payload.value) : `product_stage_${payload.productStageId || payload.value}`;

            try {
                const res = await saveWorkflowMove({
                    leadProductId,
                    customerId,
                    alternativeId,
                    productId,
                    mode: modalMode,
                    selectedStage: selectedCompanyStage,
                    productStageId: payload.productStageId || payload.value,
                    productTaskPhaseId: null,
                    reason: payload.reason,
                    teams: payload.teams,
                });

                if (res?.success !== false) {
                    await Swal.fire({ icon: 'success', title: 'Gespeichert', text: res?.message || 'Phase wurde aktualisiert.', timer: 1300, showConfirmButton: false, customClass: { container: 'cpwf-swal-front' } });
                    window.location.reload();
                } else {
                    Swal.fire({ icon: 'error', title: 'Fehler', text: res?.message || 'Phase konnte nicht gespeichert werden.', customClass: { container: 'cpwf-swal-front' } });
                }
            } catch (e) {
                Swal.fire({ icon: 'error', title: 'Fehler', text: e.message || 'Verbindungsfehler beim Speichern.', customClass: { container: 'cpwf-swal-front' } });
            }
        }

        function getVersionText(scope) {
            const label = scope?.querySelector?.('.product-version-label');
            const text = label ? label.textContent.replace(/\s+/g, ' ').trim() : '';
            return text || 'Version';
        }

        function buildCompactTeamAvatars(scope) {
            const current = getCurrentTeamAssignments(scope);
            const visible = current.slice(0, 2);
            const rest = Math.max(0, current.length - visible.length);

            if (visible.length) {
                return `<span class="cpwf-team-avatars">
                    ${visible.map(row => {
                        const emp = row.member || employeeMap().get(String(row.employee_id)) || {};
                        const name = memberName(emp, row.employee_id);
                        return `<img src="${esc(empImg(emp.image))}" title="${esc(name)}" alt="${esc(name)}">`;
                    }).join('')}
                </span>${rest > 0 ? `<strong>+${rest}</strong>` : ''}`;
            }

            const oldTeam = scope?.querySelector?.('.product-team-pill .product-team-avatars');
            if (oldTeam && oldTeam.children.length) {
                return `<span class="cpwf-team-avatars">${oldTeam.innerHTML}</span>`;
            }
            return '<span class="cpwf-team-avatars"></span>';
        }

        function addTeamAndInfoButtons() {
            document.querySelectorAll('.product-stage-flow').forEach((flow) => {
                const first = flow.querySelector('.product-stage-step');
                if (!first) return;

                const scope = flow.closest('.product-status-card')
                    || flow.closest('.custom-responsive-card')
                    || flow.closest('.house-block')
                    || flow.closest('.card')
                    || flow.parentElement;

                if (!scope || scope.querySelector('.cpwf-version-team-panel')) return;
                if (scope.querySelector('.product-team-under-version .product-team-pill')) return;

                const productId = first.dataset.productId || '';
                const customerId = first.dataset.customerId || '';
                const alternativeId = first.dataset.alternativeId || '';
                const leadProductId = first.dataset.leadProductId || getLeadProductId(productId, customerId, alternativeId) || '';
                const versionText = getVersionText(scope);

                const panel = document.createElement('div');
                panel.className = 'cpwf-version-team-panel';
                panel.innerHTML = `
                    <div class="cpwf-version-team-main">
                        <span class="cpwf-version-badge" title="Version / Objekt">
                            <i class="feather icon-tag"></i>
                            <span>${esc(versionText)}</span>
                        </span>
                        <div class="cpwf-team-row">
                            <button type="button" class="cpwf-team-btn"
                                data-product-id="${esc(productId)}"
                                data-customer-id="${esc(customerId)}"
                                data-alternative-id="${esc(alternativeId)}"
                                data-lead-product-id="${esc(leadProductId)}"
                                data-team-stage="${esc(scope?.dataset?.stage || 'lead')}"
                                data-team-assignments="${esc(scope?.dataset?.teamAssignments || '[]')}">
                                <i class="feather icon-users"></i>
                                ${buildCompactTeamAvatars(scope)}
                                <span>Team</span>
                            </button>
                        </div>
                    </div>
                    <div class="cpwf-version-team-actions">
                        <button type="button" class="cpwf-product-info-btn"
                            data-product-id="${esc(productId)}"
                            data-customer-id="${esc(customerId)}"
                            data-alternative-id="${esc(alternativeId)}"
                            title="Produktphasen anzeigen">
                            <i class="feather icon-info"></i>
                        </button>
                    </div>
                `;

                const versionLabel = scope.querySelector('.product-version-label');
                if (versionLabel) {
                    versionLabel.classList.add('cpwf-source-version');
                }

                const header = scope.querySelector('.product-card-header');
                if (header) {
                    header.insertAdjacentElement('afterend', panel);
                } else if (versionLabel) {
                    versionLabel.insertAdjacentElement('afterend', panel);
                } else {
                    const nav = flow.closest('.product-top-stage-nav') || flow.parentElement;
                    nav?.insertAdjacentElement('afterend', panel);
                }
            });

            if (window.feather?.replace) window.feather.replace();
        }

        async function showProductStageInfo(productId) {
            const stages = await loadProductStages(productId);
            if (!stages.length) {
                Swal.fire({ icon: 'info', title: 'Keine Produktphasen', text: 'Für dieses Produkt wurden keine Produktphasen gefunden.', customClass: { container: 'cpwf-swal-front' } });
                return;
            }
            Swal.fire({
                title: 'Produktphasen',
                width: 720,
                customClass: { container: 'cpwf-swal-front' },
                html: `
                    <div class="cpwf-modal-stage-list" style="text-align:left;max-height:420px;">
                        ${stages.map((s) => `
                            <div class="cpwf-stage-option">
                                <span class="cpwf-stage-icon"><i class="feather icon-${esc(s.icon || 'layers')}"></i></span>
                                <span><strong>${esc(s.name)}</strong>${s.phases?.length ? `<br><small class="text-muted">${esc(s.phases.map(p => p.name || p.phase_name).filter(Boolean).join(' • '))}</small>` : ''}</span>
                                <span></span>
                            </div>
                        `).join('')}
                    </div>
                `,
                didOpen: () => window.feather?.replace?.(),
            });
        }

        document.addEventListener('click', function (event) {
            const teamBtn = event.target.closest('.cpwf-team-btn');
            if (teamBtn) {
                event.preventDefault();
                event.stopPropagation();
                const scope = teamBtn.closest('.product-status-card')
                    || teamBtn.closest('.custom-responsive-card')
                    || teamBtn.closest('.house-block')
                    || teamBtn.closest('.card');
                openTeamHistoryModal(scope || teamBtn);
                return;
            }

            const infoBtn = event.target.closest('.cpwf-product-info-btn');
            if (infoBtn) {
                event.preventDefault();
                event.stopPropagation();
                showProductStageInfo(infoBtn.dataset.productId);
            }
        }, true);

        document.addEventListener('mouseover', function (event) {
            const step = event.target.closest('.product-stage-step');
            if (step) step.classList.add('cpwf-target-highlight');
        }, true);

        document.addEventListener('mouseout', function (event) {
            const step = event.target.closest('.product-stage-step');
            if (step) step.classList.remove('cpwf-target-highlight');
        }, true);

        window.changeProductStage = function (productId, customerId, alternativeId) {
            return openWorkflowModal({ productId, customerId, alternativeId, mode: 'company' });
        };

        window.confirmAndChangeStage = function (productId, customerId, alternativeId, selectedStage) {
            return openWorkflowModal({ productId, customerId, alternativeId, selectedStage, mode: 'company' });
        };

        window.openProductWorkflowStage = function (productId, customerId, alternativeId, selectedProductStageId) {
            return openWorkflowModal({ productId, customerId, alternativeId, selectedStage: selectedProductStageId, mode: 'product' });
        };

        window.showProductStageInfoFromElement = function (el) {
            const btn = el?.closest?.('[data-product-id]') || el;
            return showProductStageInfo(btn?.dataset?.productId);
        };

        const observer = new MutationObserver(() => addTeamAndInfoButtons());
        document.addEventListener('DOMContentLoaded', function () {
            addTeamAndInfoButtons();
            const main = document.getElementById('mainContent') || document.body;
            observer.observe(main, { childList: true, subtree: true });
        });
    })();
    </script>



    <script>
    /* =========================================================
       FINAL FIX: Google screenshot sidebar close + note context
       Problem 1:
       - Google screenshot drawer/sidebar could open but not close reliably because
         older handlers and inline state only removed one class.
       Problem 2:
       - New note composer showed "Kunde oder Alternative fehlt" because #note-list
         sometimes lost data-customer-id / data-alternative-id after AJAX partial loads.
    ========================================================= */
    (function (window, document) {
        'use strict';

        if (window.__MA_PROFILE_GOOGLE_SIDEBAR_NOTE_FIX__) {
            return;
        }
        window.__MA_PROFILE_GOOGLE_SIDEBAR_NOTE_FIX__ = true;

        function qs(selector, root) {
            return (root || document).querySelector(selector);
        }

        function qsa(selector, root) {
            return Array.prototype.slice.call((root || document).querySelectorAll(selector));
        }

        function safeCssValue(value) {
            return String(value || '').replace(/"/g, '\\"');
        }

        function getCsrfToken() {
            return document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') ||
                window.csrf ||
                '';
        }

        function showError(title, message) {
            if (window.Swal && typeof window.Swal.fire === 'function') {
                window.Swal.fire(title || 'Fehler', message || 'Ein Fehler ist aufgetreten.', 'error');
                return;
            }

            alert((title ? title + ': ' : '') + (message || 'Ein Fehler ist aufgetreten.'));
        }

        function getFirstAlternativeId() {
            var dashboardBtn = qs('.dashboard-btn[data-alternative-id]');
            if (dashboardBtn && dashboardBtn.dataset.alternativeId) {
                return dashboardBtn.dataset.alternativeId;
            }

            var firstObject = qs('.object-thumb-link[data-alternative-id], [data-object-alternative-id], [data-alternative-id]');
            if (firstObject && firstObject.dataset.alternativeId) {
                return firstObject.dataset.alternativeId;
            }

            if (firstObject && firstObject.dataset.objectAlternativeId) {
                return firstObject.dataset.objectAlternativeId;
            }

            return '';
        }

        function getCurrentNoteContext() {
            var noteList = document.getElementById('note-list');
            var activeProject = qs('.project-link.active[data-object-customer-id], .project-link.active[data-customer-id]');
            var activeObject = qs('.object-thumb-link.active[data-customer-id], .object-thumb-link[data-customer-id]');
            var dashboardBtn = qs('.dashboard-btn[data-customer-id]');
            var activeSubNav = qs('.nav-section-btn.active[data-customer-id], .ma-sub-nav-btn.active[data-customer-id]');

            var customerId =
                noteList?.dataset?.customerId ||
                activeSubNav?.dataset?.customerId ||
                activeProject?.dataset?.objectCustomerId ||
                activeProject?.dataset?.customerId ||
                activeObject?.dataset?.customerId ||
                dashboardBtn?.dataset?.customerId ||
                '';

            var alternativeId =
                noteList?.dataset?.alternativeId ||
                activeSubNav?.dataset?.alternativeId ||
                activeProject?.dataset?.objectAlternativeId ||
                activeProject?.dataset?.alternativeId ||
                activeObject?.dataset?.alternativeId ||
                dashboardBtn?.dataset?.alternativeId ||
                getFirstAlternativeId() ||
                '';

            var uniqueId =
                noteList?.dataset?.uniqueId ||
                activeProject?.dataset?.plId ||
                activeProject?.dataset?.leadProductListId ||
                '';

            var genericId =
                noteList?.dataset?.genericId ||
                noteList?.dataset?.productId ||
                activeProject?.dataset?.objectProduct ||
                activeProject?.dataset?.productId ||
                activeSubNav?.dataset?.productId ||
                '';

            var noteType =
                noteList?.dataset?.noteType ||
                (uniqueId || genericId ? 'product' : 'general');

            return {
                customerId: String(customerId || ''),
                alternativeId: String(alternativeId || ''),
                uniqueId: String(uniqueId || ''),
                genericId: String(genericId || ''),
                noteType: String(noteType || 'general')
            };
        }

        window.maEnsureNoteContext = function () {
            var noteList = document.getElementById('note-list');
            if (!noteList) return null;

            var ctx = getCurrentNoteContext();

            if (ctx.customerId) noteList.dataset.customerId = ctx.customerId;
            if (ctx.alternativeId) noteList.dataset.alternativeId = ctx.alternativeId;

            noteList.dataset.uniqueId = ctx.uniqueId || '';
            noteList.dataset.genericId = ctx.genericId || '';
            noteList.dataset.productId = ctx.genericId || '';
            noteList.dataset.noteType = ctx.noteType || 'general';

            var dashboardBtn = qs('.dashboard-btn');
            if (dashboardBtn) {
                if (ctx.customerId && !dashboardBtn.dataset.customerId) {
                    dashboardBtn.dataset.customerId = ctx.customerId;
                }
                if (ctx.alternativeId && !dashboardBtn.dataset.alternativeId) {
                    dashboardBtn.dataset.alternativeId = ctx.alternativeId;
                }
            }

            return ctx;
        };

        /* ---------------------------------------------------------
           Robust Google screenshot sidebar close
        --------------------------------------------------------- */
        function closeMapStreetView(alternativeId) {
            try {
                var map = window.MayarObjectMaps?.sidebars?.[alternativeId] ||
                    window.googleMapsInstances?.[alternativeId];

                if (map && map.getStreetView) {
                    map.getStreetView().setVisible(false);
                }
            } catch (error) {
                // no-op
            }
        }

        window.closeSidebarGallery = function (alternativeId, event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
                if (typeof event.stopImmediatePropagation === 'function') {
                    event.stopImmediatePropagation();
                }
            }

            alternativeId = String(alternativeId || '');

            var sidebar = document.getElementById('sidebarGallery' + alternativeId);
            if (!sidebar) {
                sidebar = qs('[data-gallery-sidebar].active, [data-gallery-sidebar].is-open, .sidebar-gallery.active, .sidebar-gallery.is-open');
            }

            if (!sidebar) return false;

            sidebar.classList.remove('active', 'is-open', 'show');
            sidebar.setAttribute('aria-hidden', 'true');
            sidebar.style.right = '';
            sidebar.style.visibility = '';
            sidebar.style.opacity = '';
            sidebar.style.pointerEvents = '';
            sidebar.style.transform = '';

            var objectId = alternativeId || sidebar.getAttribute('data-house-shot-root') || '';
            closeMapStreetView(objectId);

            if (window.MayarObjectMaps?.observers?.[objectId]) {
                try {
                    window.MayarObjectMaps.observers[objectId].disconnect();
                } catch (error) {
                    // no-op
                }
                delete window.MayarObjectMaps.observers[objectId];
            }

            document.body.classList.remove('house-shot-sidebar-open', 'screenshot-sidebar-open');

            return false;
        };

        window.openSidebarGallery = function (elOrAlternativeId) {
            var alternativeId = '';
            var customerId = '';
            var address = '';
            var sourceEl = null;

            if (elOrAlternativeId && typeof elOrAlternativeId === 'object' && elOrAlternativeId.dataset) {
                sourceEl = elOrAlternativeId;
                alternativeId = sourceEl.dataset.alternativeId || '';
                customerId = sourceEl.dataset.customerId || '';
                address = sourceEl.dataset.address || '';
            } else {
                alternativeId = String(elOrAlternativeId || '');
                sourceEl = qs('.object-thumb-link[data-alternative-id="' + safeCssValue(alternativeId) + '"]');
                customerId = sourceEl?.dataset?.customerId || qs('.dashboard-btn')?.dataset?.customerId || '';
                address = sourceEl?.dataset?.address || '';
            }

            if (!alternativeId) return false;

            var sidebar = document.getElementById('sidebarGallery' + alternativeId);
            if (!sidebar) return false;

            if (window.HouseScreenshotGallery && window.HouseScreenshotGallery.current) {
                window.HouseScreenshotGallery.current.customerId = customerId || window.HouseScreenshotGallery.current.customerId || '';
                window.HouseScreenshotGallery.current.alternativeId = alternativeId;
                window.HouseScreenshotGallery.current.address = address || window.HouseScreenshotGallery.current.address || '';
                window.HouseScreenshotGallery.current.sourceEl = sourceEl || window.HouseScreenshotGallery.current.sourceEl || null;
            }

            sidebar.classList.add('active', 'is-open');
            sidebar.removeAttribute('aria-hidden');
            sidebar.style.visibility = 'visible';
            sidebar.style.opacity = '1';
            sidebar.style.pointerEvents = 'auto';

            document.body.classList.add('house-shot-sidebar-open');

            var label = document.getElementById('galleryAddress' + alternativeId);
            if (label && address) {
                label.textContent = address;
            }

            if (typeof window.loadSidebarGallery === 'function') {
                window.loadSidebarGallery(customerId, alternativeId);
            }

            setTimeout(function () {
                if (typeof window.initSidebarObjectMap === 'function') {
                    window.initSidebarObjectMap(alternativeId, sourceEl);
                }
            }, 120);

            return false;
        };

        window.addEventListener('click', function (event) {
            var closeBtn = event.target && event.target.closest
                ? event.target.closest('[data-gallery-close], .ma-gallery-close, .sidebar-gallery .sidebar-header button')
                : null;

            if (!closeBtn) return;

            var sidebar = closeBtn.closest('[data-gallery-sidebar], .sidebar-gallery');
            if (!sidebar) return;

            var alternativeId = sidebar.getAttribute('data-house-shot-root') ||
                (sidebar.id || '').replace('sidebarGallery', '');

            window.closeSidebarGallery(alternativeId, event);
        }, true);

        window.addEventListener('keydown', function (event) {
            if (event.key !== 'Escape') return;

            var openSidebar = qs('[data-gallery-sidebar].active, [data-gallery-sidebar].is-open, .sidebar-gallery.active, .sidebar-gallery.is-open');
            if (!openSidebar) return;

            var alternativeId = openSidebar.getAttribute('data-house-shot-root') ||
                (openSidebar.id || '').replace('sidebarGallery', '');

            window.closeSidebarGallery(alternativeId, event);
        }, true);

        /* ---------------------------------------------------------
           Note context + safe submit override
        --------------------------------------------------------- */
        var oldToggleNewNoteArea = window.toggleNewNoteArea;
        window.toggleNewNoteArea = function (event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            window.maEnsureNoteContext();

            if (typeof oldToggleNewNoteArea === 'function') {
                return oldToggleNewNoteArea(event);
            }

            var composer = document.getElementById('newNoteComposer');
            var backdrop = document.getElementById('noteBackdrop');

            if (!composer || !backdrop) return false;

            var isOpen = composer.classList.contains('open');
            if (isOpen && typeof window.closeComposer === 'function') {
                window.closeComposer();
                return false;
            }

            composer.classList.add('open');
            backdrop.style.display = 'block';
            setTimeout(function () {
                document.getElementById('newNoteText')?.focus();
            }, 80);

            return false;
        };

        window.submitNote = async function () {
            var input = document.getElementById('newNoteText');
            var container = document.getElementById('note-list');
            var btn = qs('#newNoteComposer button[onclick*="submitNote"], #newNoteComposer button[type="button"], #newNoteComposer button');

            var text = (input?.value || '').trim();

            if (!text) {
                if (window.Swal) {
                    return window.Swal.fire('Hinweis', 'Bitte eine Notiz eingeben.', 'warning');
                }
                return alert('Bitte eine Notiz eingeben.');
            }

            if (!container) {
                return showError('Fehler', 'Notizbereich wurde nicht gefunden.');
            }

            var ctx = window.maEnsureNoteContext();

            if (!ctx || !ctx.customerId || !ctx.alternativeId) {
                return showError('Fehler', 'Kunde oder Alternative fehlt. Bitte zuerst Dashboard oder ein Produkt im linken Menü öffnen.');
            }

            var oldHtml = btn ? btn.innerHTML : '';

            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Senden...';
            }

            var payload = {
                customer_id: ctx.customerId,
                alternative_id: ctx.alternativeId,
                lead_product_list_id: ctx.uniqueId || null,
                product_id: ctx.genericId || null,
                type: ctx.noteType || 'general',
                description: text,
                priority: 'normal',
                color: '#cfe09b'
            };

            try {
                var response = await fetch('/customer-notes/store', {
                    method: 'POST',
                    headers: {
                        'X-CSRF-TOKEN': getCsrfToken(),
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify(payload)
                });

                var data = await response.json().catch(function () {
                    return {};
                });

                if (!response.ok || !data.success) {
                    throw new Error(data.message || 'Notiz konnte nicht gespeichert werden.');
                }

                if (data.html) {
                    container.insertAdjacentHTML('afterbegin', data.html);
                } else if (typeof window.showDashboard === 'function' && payload.type === 'general') {
                    window.showDashboard(qs('.dashboard-btn'));
                }

                input.value = '';

                if (typeof window.closeComposer === 'function') {
                    window.closeComposer();
                }

                if (window.feather && typeof window.feather.replace === 'function') {
                    window.feather.replace();
                }

                if (typeof window.initNoteListeners === 'function') {
                    window.initNoteListeners();
                }

            } catch (error) {
                console.error('Submit Note Error:', error);
                showError('Fehler', error.message || 'Notiz konnte nicht gespeichert werden.');
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = oldHtml || '<i class="feather icon-send me-1"></i> Senden';
                }
            }

            return false;
        };

        document.addEventListener('DOMContentLoaded', function () {
            window.maEnsureNoteContext();

            qsa('.dashboard-btn[data-customer-id]').forEach(function (btn) {
                if (!btn.dataset.alternativeId) {
                    var firstAlternativeId = getFirstAlternativeId();
                    if (firstAlternativeId) {
                        btn.dataset.alternativeId = firstAlternativeId;
                    }
                }
            });

            qsa('[onclick*="closeSidebarGallery"]').forEach(function (btn) {
                btn.setAttribute('data-gallery-close', '1');
            });
        });
    })(window, document);
    </script>


    <script>
    (function () {
        'use strict';

        if (window.__CUSTOMER_PROFILE_KANBAN_TASK_DRAWER_V2__) {
            return;
        }
        window.__CUSTOMER_PROFILE_KANBAN_TASK_DRAWER_V2__ = true;

        const CSRF_TOKEN = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}';

        const drawer = document.getElementById('customerKanbanTaskDrawer');
        const titleEl = document.getElementById('customerKanbanTaskTitle');
        const subtitleEl = document.getElementById('customerKanbanTaskSubtitle');
        const errorEl = document.getElementById('customerKanbanTaskError');
        const loadingEl = document.getElementById('customerKanbanTaskLoading');
        const contentEl = document.getElementById('customerKanbanTaskContent');
        const contextEl = document.getElementById('customerKanbanTaskContext');
        const contextBadgeEl = document.getElementById('customerKanbanTaskContextBadge');

        const currentBoxEl = document.getElementById('customerKanbanCurrentTaskBox');
        const responsibleValueEl = document.getElementById('customerKanbanResponsibleValue');
        const nextStepValueEl = document.getElementById('customerKanbanNextStepValue');
        const sollValueEl = document.getElementById('customerKanbanSollValue');
        const istDiffValueEl = document.getElementById('customerKanbanIstDiffValue');
        const progressTextEl = document.getElementById('customerKanbanProgressText');
        const progressPercentEl = document.getElementById('customerKanbanProgressPercent');
        const progressBarEl = document.getElementById('customerKanbanProgressBar');
        const progressOpenEl = document.getElementById('customerKanbanProgressOpen');

        const openListEl = document.getElementById('customerKanbanOpenTaskList');
        const doneListEl = document.getElementById('customerKanbanDoneTaskList');
        const openCountEl = document.getElementById('customerKanbanOpenCount');
        const doneCountEl = document.getElementById('customerKanbanDoneCount');
        const taskCountEl = document.getElementById('customerKanbanTaskCount');

        const templateListEl = document.getElementById('customerKanbanTaskTemplates');
        const templateCountEl = document.getElementById('customerKanbanTemplateCount');
        const templateCountMirrorEl = document.getElementById('customerKanbanTemplateCountMirror');
        const templateSearchEl = document.getElementById('customerKanbanTemplateSearch');
        const templateSectionFilterEl = document.getElementById('customerKanbanTemplateSectionFilter');
        const templateTypeFilterEl = document.getElementById('customerKanbanTemplateTypeFilter');
        let lastTemplateRows = [];

        const manualForm = document.getElementById('customerKanbanManualTaskForm');
        const manualBox = document.getElementById('customerKanbanManualTaskBox');
        const manualToggle = document.getElementById('customerKanbanManualToggle');
        const leadInput = document.getElementById('customerKanbanLeadProductId');
        const performerSelect = document.getElementById('customerKanbanTaskPerformer');

        let activeLeadProductId = null;
        let activeFieldProgress = null;
        let activeEmployees = [];
        let summaryRefreshTimer = null;

        function escapeHtml(value) {
            return String(value ?? '').replace(/[&<>"']/g, function (char) {
                return {
                    '&': '&amp;',
                    '<': '&lt;',
                    '>': '&gt;',
                    '"': '&quot;',
                    "'": '&#039;'
                }[char];
            });
        }

        function normalizeStatus(status) {
            return String(status || 'open').toLowerCase();
        }

        function statusLabel(status) {
            return {
                open: 'Offen',
                scheduled: 'Geplant',
                in_progress: 'In Bearbeitung',
                reported: 'Zu prüfen',
                done: 'Erledigt',
                cancelled: 'Abgebrochen'
            }[normalizeStatus(status)] || (status || 'Offen');
        }

        function isDoneTask(task) {
            return normalizeStatus(task?.status) === 'done';
        }

        function isCancelledTask(task) {
            return normalizeStatus(task?.status) === 'cancelled';
        }

        function isOpenTask(task) {
            return !isDoneTask(task) && !isCancelledTask(task);
        }

        function performerName(task) {
            const performer = task?.performer || {};
            return performer.display_name || [performer.lastname, performer.name].filter(Boolean).join(' ') || '-';
        }

        function parseDate(value) {
            if (!value) return null;
            const normalized = String(value).replace(' ', 'T');
            const date = new Date(normalized);
            return Number.isNaN(date.getTime()) ? null : date;
        }

        function minutesBetween(start, end) {
            const a = parseDate(start);
            const b = parseDate(end);
            if (!a || !b) return null;
            return Math.round((b.getTime() - a.getTime()) / 60000);
        }

        function formatMinutes(minutes) {
            if (minutes === null || minutes === undefined || Number.isNaN(Number(minutes))) {
                return '–';
            }

            const value = Number(minutes);
            const sign = value < 0 ? '-' : '';
            const abs = Math.abs(value);
            const h = Math.floor(abs / 60);
            const m = abs % 60;

            if (h <= 0) {
                return `${sign}${m} Min.`;
            }

            return `${sign}${h}h ${String(m).padStart(2, '0')}m`;
        }

        function firstDateValue(values) {
            return values
                .map(parseDate)
                .filter(Boolean)
                .sort((a, b) => a.getTime() - b.getTime())[0] || null;
        }

        function formatDateTimeShort(value) {
            const date = value instanceof Date ? value : parseDate(value);
            if (!date) return '–';

            const pad = number => String(number).padStart(2, '0');
            return `${pad(date.getDate())}.${pad(date.getMonth() + 1)}.${date.getFullYear()} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
        }

        function sumTaskMinutes(tasks, resolver) {
            return (Array.isArray(tasks) ? tasks : []).reduce(function (sum, task) {
                const value = resolver(task);
                return value === null || value === undefined || Number.isNaN(Number(value))
                    ? sum
                    : sum + Number(value);
            }, 0);
        }

        function totalTimeSummary(tasks) {
            const list = Array.isArray(tasks) ? tasks.filter(task => !isCancelledTask(task)) : [];
            const plan = sumTaskMinutes(list, task => task.estimated_minutes ? Number(task.estimated_minutes) : null);
            const actual = sumTaskMinutes(list, function (task) {
                if (task.done_at) {
                    return minutesBetween(task.planned_start_at, task.done_at);
                }

                if (normalizeStatus(task.status) === 'in_progress' && task.planned_start_at) {
                    return minutesBetween(task.planned_start_at, new Date().toISOString());
                }

                return null;
            });

            const diff = plan && actual ? actual - plan : null;
            const deviation = plan && diff !== null ? Math.round((diff / plan) * 100) : null;
            const firstStart = firstDateValue(list.map(task => task.planned_start_at || task.created_at));

            return {
                plan,
                actual,
                diff,
                deviation,
                firstStart,
                planLabel: formatMinutes(plan || null),
                actualLabel: formatMinutes(actual || null),
                diffLabel: formatMinutes(diff),
                deviationLabel: deviation === null ? '–' : `${deviation > 0 ? '+' : ''}${deviation}%`
            };
        }

        function timeSummaryForTask(task) {
            const soll = task?.estimated_minutes ? Number(task.estimated_minutes) : null;
            const ist = minutesBetween(task?.planned_start_at, task?.done_at || task?.planned_end_at);
            const diff = soll !== null && ist !== null ? ist - soll : null;

            return {
                soll,
                ist,
                diff,
                label: `Soll ${formatMinutes(soll)} · Ist ${formatMinutes(ist)} · Diff ${formatMinutes(diff)}`
            };
        }

        function taskBuckets(tasks) {
            const list = Array.isArray(tasks) ? tasks : [];
            const open = list.filter(isOpenTask);
            const done = list.filter(isDoneTask);
            const current = open.find(task => normalizeStatus(task.status) === 'in_progress')
                || open.find(task => normalizeStatus(task.status) === 'scheduled')
                || open[0]
                || null;
            const next = current
                ? open.find(task => String(task.id) !== String(current.id)) || null
                : open[0] || null;

            return { list, open, done, current, next };
        }

        function progressData(tasks) {
            const { list, done, open } = taskBuckets(tasks);
            const total = list.filter(task => !isCancelledTask(task)).length;
            const doneCount = done.length;
            const openCount = open.length;
            const percent = total > 0 ? Math.round((doneCount / total) * 100) : 0;

            return { total, doneCount, openCount, percent };
        }

        function showLoading() {
            if (errorEl) errorEl.style.display = 'none';
            if (contentEl) contentEl.style.display = 'none';
            if (loadingEl) loadingEl.style.display = 'block';
        }

        function showError(message) {
            if (loadingEl) loadingEl.style.display = 'none';
            if (contentEl) contentEl.style.display = 'none';
            if (errorEl) {
                errorEl.textContent = message || 'Fehler beim Laden.';
                errorEl.style.display = 'block';
            }
        }

        function showContent() {
            if (loadingEl) loadingEl.style.display = 'none';
            if (errorEl) errorEl.style.display = 'none';
            if (contentEl) contentEl.style.display = 'block';
        }

        function openDrawer() {
            if (!drawer) return;
            drawer.classList.add('is-open');
            drawer.setAttribute('aria-hidden', 'false');
            document.body.classList.add('kb-task-profile-open');
        }

        function closeDrawer() {
            if (!drawer) return;
            drawer.classList.remove('is-open');
            drawer.setAttribute('aria-hidden', 'true');
            document.body.classList.remove('kb-task-profile-open');
        }

        async function fetchJson(url, options = {}) {
            const optionHeaders = options.headers || {};
            const fetchOptions = { ...options };
            delete fetchOptions.headers;

            const response = await fetch(url, {
                credentials: 'same-origin',
                ...fetchOptions,
                headers: {
                    'Accept': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                    'X-CSRF-TOKEN': CSRF_TOKEN,
                    ...optionHeaders
                }
            });

            const text = await response.text();
            let data = {};

            try {
                data = text ? JSON.parse(text) : {};
            } catch (error) {
                throw new Error(text || 'Ungültige Serverantwort.');
            }

            if (!response.ok || data.success === false) {
                throw new Error(data.message || 'Serverfehler.');
            }

            return data;
        }

        function formPayload(form) {
            const formData = new FormData(form);
            const payload = {};

            formData.forEach(function (value, key) {
                if (key.endsWith('[]')) {
                    const cleanKey = key.slice(0, -2);
                    payload[cleanKey] = payload[cleanKey] || [];
                    payload[cleanKey].push(value);
                    return;
                }

                if (payload[key] !== undefined) {
                    payload[key] = Array.isArray(payload[key]) ? payload[key] : [payload[key]];
                    payload[key].push(value);
                    return;
                }

                payload[key] = value;
            });

            ['is_scheduled'].forEach(function (key) {
                payload[key] = !!form.querySelector(`[name="${key}"]`)?.checked;
            });

            return payload;
        }

        function renderEmployees(employees, selectedId) {
            activeEmployees = Array.isArray(employees) ? employees : [];

            if (!performerSelect) return;

            performerSelect.innerHTML = '<option value="">Automatisch / aktueller Benutzer</option>';

            activeEmployees.forEach(function (employee) {
                const option = document.createElement('option');
                option.value = employee.id;
                option.textContent = employee.text || `${employee.lastname || ''} ${employee.name || ''}`.trim() || `#${employee.id}`;

                if (selectedId && Number(selectedId) === Number(employee.id)) {
                    option.selected = true;
                }

                performerSelect.appendChild(option);
            });
        }

        function renderContext(context) {
            const rows = [
                ['Kunde', context.customer_name || '-'],
                ['Produkt', context.product_name || '-'],
                ['Phase', context.stage_label || '-'],
                ['Unterphase', context.sub_stage_label || '-']
            ];

            if (contextEl) {
                contextEl.innerHTML = rows.map(function ([label, value]) {
                    return `
                        <div class="kb-task-profile-info-item">
                            <div class="kb-task-profile-info-label">${escapeHtml(label)}</div>
                            <div class="kb-task-profile-info-value">${escapeHtml(value)}</div>
                        </div>
                    `;
                }).join('');
            }

            if (titleEl) {
                titleEl.textContent = `Aufgaben: ${context.product_name || 'Produkt'}`;
            }

            if (subtitleEl) {
                subtitleEl.textContent = [context.customer_name, context.stage_label, context.sub_stage_label]
                    .filter(Boolean)
                    .join(' • ') || 'Kanban Aufgabenmanagement';
            }

            if (contextBadgeEl) {
                contextBadgeEl.textContent = `LeadProduct #${context.lead_product_list_id || '-'}`;
            }
        }

        function renderEnterpriseHero(tasks) {
            const { list, open, done, current, next } = taskBuckets(tasks);
            const progress = progressData(tasks);
            const currentTime = timeSummaryForTask(current || {});
            const activeStatus = current ? statusLabel(current.status) : 'Keine aktive Aufgabe';

            if (currentBoxEl) {
                currentBoxEl.innerHTML = current ? `
                    <div class="kb-enterprise-current-title">${escapeHtml(current.title || 'Aufgabe')}</div>
                    ${current.description ? `<div class="kb-enterprise-current-desc">${escapeHtml(current.description)}</div>` : ''}
                    <div class="kb-task-profile-meta mt-2">
                        <span class="kb-task-profile-pill">${escapeHtml(activeStatus)}</span>
                        ${current.is_overdue ? '<span class="kb-task-profile-pill" style="border-color:#f8ac00;background:rgba(248,172,0,.16);">Überfällig</span>' : ''}
                        ${current.photo_required ? '<span class="kb-task-profile-pill">Foto erforderlich</span>' : ''}
                    </div>
                ` : `
                    <div class="kb-enterprise-current-title">Keine aktive Aufgabe</div>
                    <div class="kb-enterprise-current-desc">Es gibt noch keine offene Aufgabe. Erstellen Sie eine manuelle Aufgabe oder übernehmen Sie eine Vorlage.</div>
                `;
            }

            if (responsibleValueEl) responsibleValueEl.textContent = current ? performerName(current) : '–';
            if (nextStepValueEl) nextStepValueEl.textContent = next?.title || '–';
            if (sollValueEl) sollValueEl.textContent = formatMinutes(currentTime.soll);
            if (istDiffValueEl) istDiffValueEl.textContent = `${formatMinutes(currentTime.ist)} / ${formatMinutes(currentTime.diff)}`;

            const fp = activeFieldProgress || { gesamt: 0, erledigt: 0, offen: 0, percent: 0 };
            if (progressTextEl) progressTextEl.textContent = `${fp.erledigt} von ${fp.gesamt}`;
            if (progressPercentEl) progressPercentEl.textContent = `${fp.percent}%`;
            if (progressBarEl) progressBarEl.style.width = `${fp.percent}%`;
            if (progressOpenEl) progressOpenEl.textContent = `${fp.offen} offen`;

            if (taskCountEl) taskCountEl.textContent = `${fp.gesamt} Aufgaben`;
            if (openCountEl) openCountEl.textContent = String(open.length);
            if (doneCountEl) doneCountEl.textContent = String(done.length);
        }

        function taskCardHtml(task, isActive) {
            const performer = performerName(task);
            const time = timeSummaryForTask(task);
            const employeeBadges = Array.isArray(task.employees) && task.employees.length
                ? task.employees.map(emp => `<span class="kb-task-profile-pill">${escapeHtml(emp.display_name || emp.name || ('#' + emp.id))}</span>`).join('')
                : '';

            return `
                <div class="kb-task-profile-task ${isDoneTask(task) ? 'is-done' : ''} ${isActive ? 'is-active-task' : ''} ${task.is_overdue ? 'is-overdue' : ''}" data-task-id="${escapeHtml(task.id)}">
                    <div class="kb-task-profile-task-head">
                        <div>
                            <div class="kb-task-profile-task-title">${escapeHtml(task.title || 'Aufgabe')}</div>
                            ${task.description ? `<div class="kb-task-profile-task-desc">${escapeHtml(task.description)}</div>` : ''}
                        </div>
                        <span class="kb-task-profile-pill">${escapeHtml(statusLabel(task.status))}</span>
                    </div>

                    <div class="kb-task-profile-meta">
                        <span class="kb-task-profile-pill">Zuständig: ${escapeHtml(performer)}</span>
                        ${normalizeStatus(task.status) === 'reported' && task.reviewer ? `<span class="kb-task-profile-pill">Zu prüfen bei: ${escapeHtml(task.reviewer.display_name || '')}</span>` : ''}
                        ${task.planned_start_at ? `<span class="kb-task-profile-pill">Start: ${escapeHtml(task.planned_start_at)}</span>` : ''}
                        ${task.planned_end_at ? `<span class="kb-task-profile-pill">Ende: ${escapeHtml(task.planned_end_at)}</span>` : ''}
                        <span class="kb-task-profile-pill">${escapeHtml(time.label)}</span>
                        ${task.photo_required ? '<span class="kb-task-profile-pill">Foto erforderlich</span>' : ''}
                        ${employeeBadges}
                    </div>

                    <div class="kb-task-profile-actions">
                        <button type="button" class="btn btn-outline-secondary js-profile-task-status" data-status="open">Offen</button>
                        <button type="button" class="btn btn-outline-warning js-profile-task-status" data-status="scheduled">Geplant</button>
                        <button type="button" class="btn btn-outline-primary js-profile-task-status" data-status="in_progress">Play</button>
                        <button type="button" class="btn btn-outline-success js-profile-task-status" data-status="done">Erledigt</button>
                        <button type="button" class="btn btn-outline-danger js-profile-task-delete">Löschen</button>
                    </div>
                </div>
            `;
        }

        function renderTasks(tasks) {
            const { open, done, current } = taskBuckets(tasks);

            renderEnterpriseHero(tasks);

            if (openListEl) {
                openListEl.innerHTML = open.length
                    ? open.map(task => taskCardHtml(task, current && String(task.id) === String(current.id))).join('')
                    : '<div class="kb-task-profile-empty">Keine offene oder aktive Aufgabe vorhanden.</div>';
            }

            if (doneListEl) {
                doneListEl.innerHTML = done.length
                    ? done.map(task => taskCardHtml(task, false)).join('')
                    : '<div class="kb-task-profile-empty">Noch keine erledigte Aufgabe gespeichert.</div>';
            }
        }

        function flattenTemplates(templates) {
            const rows = [];

            (Array.isArray(templates) ? templates : []).forEach(function (phase) {
                const activities = Array.isArray(phase.activities) ? phase.activities : [];

                if (activities.length) {
                    activities.forEach(function (activity) {
                        rows.push({
                            task_phase_id: phase.id,
                            phase_activity_id: activity.id,
                            title: activity.title || phase.phase_name || 'Vorlage',
                            description: activity.description || phase.description || '',
                            section_name: phase.section_name || '',
                            estimated_minutes: activity.estimated_minutes || '',
                            photo_required: !!activity.photo_required
                        });
                    });
                    return;
                }

                rows.push({
                    task_phase_id: phase.id,
                    phase_activity_id: null,
                    title: phase.phase_name || 'Vorlage',
                    description: phase.description || '',
                    section_name: phase.section_name || '',
                    estimated_minutes: '',
                    photo_required: false
                });
            });

            return rows.filter(row => row.task_phase_id);
        }

        function syncTemplateSectionOptions(rows) {
            if (!templateSectionFilterEl) return;

            const currentValue = templateSectionFilterEl.value || '';
            const sections = Array.from(new Set(
                rows
                    .map(row => String(row.section_name || '').trim())
                    .filter(Boolean)
            )).sort((a, b) => a.localeCompare(b, 'de'));

            templateSectionFilterEl.innerHTML = '<option value="">Alle Abschnitte</option>' + sections.map(section => {
                return `<option value="${escapeHtml(section)}">${escapeHtml(section)}</option>`;
            }).join('');

            if (sections.includes(currentValue)) {
                templateSectionFilterEl.value = currentValue;
            }
        }

        function applyTemplateFilters() {
            if (!templateListEl) return;

            const query = String(templateSearchEl?.value || '').trim().toLowerCase();
            const section = String(templateSectionFilterEl?.value || '').trim().toLowerCase();
            const type = String(templateTypeFilterEl?.value || '').trim();
            const cards = Array.from(templateListEl.querySelectorAll('.kb-task-profile-template'));
            let visible = 0;

            cards.forEach(function (card) {
                const haystack = String(card.dataset.search || '').toLowerCase();
                const cardSection = String(card.dataset.section || '').toLowerCase();
                const hasPhoto = card.dataset.photo === '1';
                const hasTime = card.dataset.time === '1';

                const matchesSearch = !query || haystack.includes(query);
                const matchesSection = !section || cardSection === section;
                const matchesType = !type || (type === 'photo' && hasPhoto) || (type === 'time' && hasTime);
                const show = matchesSearch && matchesSection && matchesType;

                card.classList.toggle('is-hidden', !show);
                if (show) visible++;
            });

            const empty = templateListEl.querySelector('.kb-template-no-results');
            if (empty) {
                empty.classList.toggle('is-visible', cards.length > 0 && visible === 0);
            }

            if (templateCountEl) {
                templateCountEl.textContent = cards.length ? `${visible}/${cards.length}` : '0';
            }
            if (templateCountMirrorEl) {
                templateCountMirrorEl.textContent = cards.length ? `${visible}/${cards.length}` : '0';
            }
        }

        function renderTemplates(templates) {
            const rows = flattenTemplates(templates);
            lastTemplateRows = rows;

            if (templateCountEl) templateCountEl.textContent = String(rows.length);
            if (templateCountMirrorEl) templateCountMirrorEl.textContent = String(rows.length);
            syncTemplateSectionOptions(rows);

            if (!templateListEl) return;

            if (!rows.length) {
                templateListEl.innerHTML = '<div class="kb-task-profile-empty">Keine Vorlagen für diese Phase/Subphase gefunden.</div>';
                return;
            }

            templateListEl.innerHTML = rows.map(function (row) {
                const searchText = [row.title, row.description, row.section_name, row.estimated_minutes ? 'soll zeit minuten' : '', row.photo_required ? 'foto erforderlich' : '']
                    .filter(Boolean)
                    .join(' ');

                return `
                    <div class="kb-task-profile-template"
                         data-search="${escapeHtml(searchText)}"
                         data-section="${escapeHtml(row.section_name || '')}"
                         data-photo="${row.photo_required ? '1' : '0'}"
                         data-time="${row.estimated_minutes ? '1' : '0'}">
                        <div class="kb-task-profile-task-title">${escapeHtml(row.title)}</div>
                        ${row.description ? `<div class="kb-task-profile-task-desc">${escapeHtml(row.description)}</div>` : ''}
                        <div class="kb-task-profile-meta">
                            ${row.section_name ? `<span class="kb-task-profile-pill">${escapeHtml(row.section_name)}</span>` : ''}
                            ${row.estimated_minutes ? `<span class="kb-task-profile-pill">Soll: ${escapeHtml(row.estimated_minutes)} Min.</span>` : ''}
                            ${row.photo_required ? '<span class="kb-task-profile-pill">Foto erforderlich</span>' : ''}
                        </div>
                        <button type="button"
                                class="btn btn-success kb-task-profile-template-btn js-profile-create-template-task mt-2"
                                data-task-phase-id="${escapeHtml(row.task_phase_id)}"
                                data-phase-activity-id="${escapeHtml(row.phase_activity_id || '')}"
                                data-template-title="${escapeHtml(row.title || '')}"
                                data-template-section="${escapeHtml(row.section_name || '')}"
                                data-estimated-minutes="${escapeHtml(row.estimated_minutes || '')}">
                            <i class="feather icon-plus"></i> Aus Vorlage erstellen
                        </button>
                    </div>
                `;
            }).join('') + '<div class="kb-template-no-results">Keine Vorlage passt zu Suche/Filter.</div>';

            applyTemplateFilters();
        }


        function localDateTimeValue(date) {
            const pad = value => String(value).padStart(2, '0');
            return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
        }

        function defaultTaskDateValues(minutes) {
            const start = new Date();
            start.setMinutes(Math.ceil(start.getMinutes() / 15) * 15, 0, 0);
            const end = new Date(start.getTime() + (Number(minutes || 60) * 60000));

            return {
                start: localDateTimeValue(start),
                end: localDateTimeValue(end)
            };
        }

        function employeeSelectOptions(selectedId) {
            const options = ['<option value="">Aktueller Benutzer / automatisch</option>'];

            activeEmployees.forEach(function (employee) {
                const text = employee.text || [employee.lastname, employee.name].filter(Boolean).join(' ') || `#${employee.id}`;
                const selected = selectedId && String(selectedId) === String(employee.id) ? 'selected' : '';
                options.push(`<option value="${escapeHtml(employee.id)}" ${selected}>${escapeHtml(text)}</option>`);
            });

            return options.join('');
        }

        async function askTemplateTaskOptions(templateBtn) {
            const estimatedMinutes = templateBtn.dataset.estimatedMinutes || '';
            const dates = defaultTaskDateValues(estimatedMinutes || 60);
            const currentPerformer = performerSelect?.value || '';
            const templateTitle = templateBtn.dataset.templateTitle || 'Vorlage';
            const templateSection = templateBtn.dataset.templateSection || '';

            if (!window.Swal) {
                const due = window.prompt('Bis wann soll die Aufgabe erledigt sein? Format: YYYY-MM-DD HH:mm', dates.end.replace('T', ' '));
                if (due === null) return null;

                return {
                    is_scheduled: true,
                    planned_start_at: dates.start,
                    planned_end_at: due.trim().replace(' ', 'T'),
                    estimated_minutes: estimatedMinutes || null,
                    performer_employee_id: currentPerformer || null,
                    employee_ids: currentPerformer ? [currentPerformer] : [],
                    create_personal_task: false,
                    create_appointment: false,
                    appointment_type: 'kanban_task',
                    appointment_contact_mode: null,
                    appointment_priority: 'normal'
                };
            }

            const result = await Swal.fire({
                title: 'Aus Vorlage erstellen',
                width: 720,
                showCancelButton: true,
                confirmButtonText: 'Erstellen',
                cancelButtonText: 'Abbrechen',
                focusConfirm: false,
                html: `
                    <div class="text-left" style="font-size:13px;">
                        <div style="padding:10px 12px;border:1px solid #c0d8ea;border-radius:14px;margin-bottom:12px;background:#f8fbfd;">
                            <div style="font-weight:900;color:#74b2d4;">${escapeHtml(templateTitle)}</div>
                            ${templateSection ? `<div style="margin-top:3px;color:#6b7280;">${escapeHtml(templateSection)}</div>` : ''}
                        </div>

                        <div class="row">
                            <div class="col-md-6 mb-2">
                                <label style="font-weight:800;">Start / geplant ab</label>
                                <input type="datetime-local" id="tplPlannedStart" class="swal2-input" style="width:100%;margin:0;" value="${escapeHtml(dates.start)}">
                            </div>
                            <div class="col-md-6 mb-2">
                                <label style="font-weight:800;">Bis wann erledigen?</label>
                                <input type="datetime-local" id="tplPlannedEnd" class="swal2-input" style="width:100%;margin:0;" value="${escapeHtml(dates.end)}">
                            </div>
                        </div>

                        <div class="row">
                            <div class="col-md-6 mb-2">
                                <label style="font-weight:800;">Zuständig</label>
                                <select id="tplPerformer" class="swal2-select" style="width:100%;margin:0;">
                                    ${employeeSelectOptions(currentPerformer)}
                                </select>
                            </div>
                            <div class="col-md-6 mb-2">
                                <label style="font-weight:800;">Soll-Zeit Minuten</label>
                                <input type="number" min="1" id="tplEstimatedMinutes" class="swal2-input" style="width:100%;margin:0;" value="${escapeHtml(estimatedMinutes || '')}" placeholder="z.B. 60">
                            </div>
                        </div>

                        <div style="display:grid;gap:8px;margin-top:10px;">
                            <label style="display:flex;align-items:center;gap:8px;margin:0;">
                                <input type="checkbox" id="tplCreatePersonalTask">
                                <span>Auch als persönliche Aufgabe erstellen</span>
                            </label>
                            <label style="display:flex;align-items:center;gap:8px;margin:0;">
                                <input type="checkbox" id="tplCreateAppointment">
                                <span>Auch als Termin im Kalender erstellen</span>
                            </label>
                        </div>

                        <div id="tplAppointmentOptions" style="display:none;margin-top:10px;padding:10px;border:1px dashed #c0d8ea;border-radius:14px;">
                            <div class="row">
                                <div class="col-md-4 mb-2">
                                    <label style="font-weight:800;">Terminart</label>
                                    <input type="text" id="tplAppointmentType" class="swal2-input" style="width:100%;margin:0;" value="kanban_task">
                                </div>
                                <div class="col-md-4 mb-2">
                                    <label style="font-weight:800;">Kontaktart</label>
                                    <select id="tplContactMode" class="swal2-select" style="width:100%;margin:0;">
                                        <option value="">Keine</option>
                                        <option value="phone">Telefon</option>
                                        <option value="email">E-Mail</option>
                                        <option value="onsite">Vor Ort</option>
                                        <option value="video">Video</option>
                                    </select>
                                </div>
                                <div class="col-md-4 mb-2">
                                    <label style="font-weight:800;">Priorität</label>
                                    <select id="tplPriority" class="swal2-select" style="width:100%;margin:0;">
                                        <option value="normal">Normal</option>
                                        <option value="high">Hoch</option>
                                        <option value="urgent">Dringend</option>
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>
                `,
                didOpen: function () {
                    const appointmentCheck = document.getElementById('tplCreateAppointment');
                    const appointmentOptions = document.getElementById('tplAppointmentOptions');

                    appointmentCheck?.addEventListener('change', function () {
                        appointmentOptions.style.display = appointmentCheck.checked ? 'block' : 'none';
                    });
                },
                preConfirm: function () {
                    const start = document.getElementById('tplPlannedStart')?.value || '';
                    const end = document.getElementById('tplPlannedEnd')?.value || '';
                    const performer = document.getElementById('tplPerformer')?.value || '';
                    const estimated = document.getElementById('tplEstimatedMinutes')?.value || '';
                    const createPersonalTask = document.getElementById('tplCreatePersonalTask')?.checked || false;
                    const createAppointment = document.getElementById('tplCreateAppointment')?.checked || false;

                    if (!end) {
                        Swal.showValidationMessage('Bitte wählen Sie, bis wann die Aufgabe erledigt sein soll.');
                        return false;
                    }

                    if (createAppointment && !start) {
                        Swal.showValidationMessage('Für einen Termin muss auch Start / geplant ab gesetzt sein.');
                        return false;
                    }

                    return {
                        is_scheduled: !!(start || end),
                        planned_start_at: start || null,
                        planned_end_at: end || null,
                        estimated_minutes: estimated || null,
                        performer_employee_id: performer || null,
                        employee_ids: performer ? [performer] : [],
                        create_personal_task: createPersonalTask,
                        create_appointment: createAppointment,
                        appointment_type: document.getElementById('tplAppointmentType')?.value || 'kanban_task',
                        appointment_contact_mode: document.getElementById('tplContactMode')?.value || null,
                        appointment_priority: document.getElementById('tplPriority')?.value || 'normal'
                    };
                }
            });

            return result.isConfirmed ? result.value : null;
        }

        async function loadKanbanTaskContext(leadProductId) {
            activeLeadProductId = leadProductId;

            if (leadInput) {
                leadInput.value = leadProductId;
            }

            showLoading();

            const data = await fetchJson(`/admin/kanban/tasks/context/${encodeURIComponent(leadProductId)}`);

            activeFieldProgress = data.field_progress || null;

            renderContext(data.context || {});
            renderEmployees(data.employees || [], data.auth_employee_id || null);
            renderTasks(data.tasks || []);
            renderTemplates(data.templates || []);
            showContent();

            if (window.feather) {
                window.feather.replace();
            }

            refreshProfileKanbanTaskSummaries();
        }

        function updateProductTaskCard(leadProductId, summary) {
            const cards = document.querySelectorAll(`.js-profile-kanban-task-summary[data-lead-product-list-id="${CSS.escape(String(leadProductId))}"]`);

            if (!cards.length) return;

            const tasks = Array.isArray(summary?.tasks) ? summary.tasks : [];
            const { current, next } = taskBuckets(tasks);
            const progress = progressData(tasks);
            const time = timeSummaryForTask(current || {});
            const openCount = progress.openCount;
            const statusPill = current
                ? (normalizeStatus(current.status) === 'in_progress' ? 'is-play' : 'is-open')
                : '';

            cards.forEach(function (card) {
                card.classList.toggle('is-empty', progress.total === 0);

                const pill = card.querySelector('.pkt-head .pkt-pill');
                if (pill) {
                    pill.className = `pkt-pill ${statusPill}`;
                    pill.textContent = current ? statusLabel(current.status) : 'Keine Aufgabe';
                }

                const currentEl = card.querySelector('[data-pkt-current]');
                if (currentEl) currentEl.textContent = current?.title || summary?.current_title || 'Keine offene Aufgabe';

                const nextEl = card.querySelector('[data-pkt-next]');
                if (nextEl) nextEl.textContent = `Nächster Schritt: ${next?.title || summary?.next_title || '–'}`;

                const responsibleEl = card.querySelector('[data-pkt-responsible]');
                if (responsibleEl) responsibleEl.textContent = current ? performerName(current) : '–';

                const timeEl = card.querySelector('[data-pkt-time]');
                if (timeEl) timeEl.textContent = time.label;

                const openEl = card.querySelector('[data-pkt-open]');
                if (openEl) openEl.textContent = `${openCount} offen`;

                const countEl = card.querySelector('[data-pkt-count]');
                if (countEl) countEl.textContent = `${progress.doneCount}/${progress.total}`;

                const barEl = card.querySelector('[data-pkt-bar]');
                if (barEl) barEl.style.width = `${progress.percent}%`;
            });

            const timeSummaryCards = document.querySelectorAll(`.js-kanban-task-time-summary[data-lead-product-list-id="${CSS.escape(String(leadProductId))}"]`);
            const totals = totalTimeSummary(tasks);
            const iconName = progress.total === 0
                ? 'minus-circle'
                : (totals.diff !== null && totals.diff > 0 ? 'alert-circle' : 'check-circle');
            const iconClass = progress.total === 0
                ? 'text-muted'
                : (totals.diff !== null && totals.diff > 0 ? 'text-warning' : 'text-success');

            timeSummaryCards.forEach(function (box) {
                const startEl = box.querySelector('[data-task-start]');
                if (startEl) startEl.textContent = formatDateTimeShort(totals.firstStart || summary?.stage_landed_at);

                const planEl = box.querySelector('[data-task-plan]');
                if (planEl) planEl.textContent = totals.planLabel;

                const istEl = box.querySelector('[data-task-ist]');
                if (istEl) istEl.textContent = totals.actualLabel;

                const diffEl = box.querySelector('[data-task-diff]');
                if (diffEl) diffEl.textContent = totals.diffLabel;

                const abwEl = box.querySelector('[data-task-abw]');
                if (abwEl) abwEl.textContent = totals.deviationLabel;

                const progressWrap = box.querySelector('[data-task-progress-title]');
                if (progressWrap) progressWrap.setAttribute('title', `${progress.doneCount} von ${progress.total} erledigt`);

                const progressBar = box.querySelector('[data-task-progress-bar]');
                if (progressBar) {
                    progressBar.style.width = `${progress.percent}%`;
                    progressBar.className = `progress-bar ${progress.total === 0 ? 'bg-secondary' : (progress.percent >= 100 ? 'bg-success' : 'bg-primary')}`;
                }

                const progressCount = box.querySelector('[data-task-progress-count]');
                if (progressCount) progressCount.textContent = `${progress.doneCount}/${progress.total}`;

                const icon = box.querySelector('[data-task-time-icon]');
                if (icon) {
                    icon.className = `feather icon-${iconName} ${iconClass}`;
                    icon.setAttribute('title', progress.total === 0 ? 'Keine Aufgaben' : `Plan ${totals.planLabel}, Ist ${totals.actualLabel}, Diff ${totals.diffLabel}`);
                }
            });
        }

        async function refreshProfileKanbanTaskSummaries() {
            const ids = Array.from(document.querySelectorAll('.js-profile-kanban-task-summary[data-lead-product-list-id], .open-kanban-task-modal[data-lead-product-list-id]'))
                .map(el => el.dataset.leadProductListId)
                .filter(Boolean)
                .filter((value, index, arr) => arr.indexOf(value) === index);

            if (!ids.length) return;

            try {
                const data = await fetchJson('/admin/kanban/tasks/summaries', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ _token: CSRF_TOKEN, lead_product_list_ids: ids })
                });

                const summaries = data.summaries || {};
                Object.keys(summaries).forEach(function (leadProductId) {
                    updateProductTaskCard(leadProductId, summaries[leadProductId]);
                });

                if (window.feather) {
                    window.feather.replace();
                }
            } catch (error) {
                console.warn('Kanban task summary refresh failed:', error.message || error);
            }
        }

        function scheduleSummaryRefresh() {
            clearTimeout(summaryRefreshTimer);
            summaryRefreshTimer = setTimeout(refreshProfileKanbanTaskSummaries, 250);
        }

        window.openCustomerKanbanTaskDrawer = async function (leadProductId) {
            if (!leadProductId) {
                if (window.Swal) {
                    Swal.fire({
                        icon: 'error',
                        title: 'LeadProduct-ID fehlt',
                        text: 'Die Produktkarte hat keine data-lead-product-list-id. Bitte lead_product_lists.id in den Button setzen.'
                    });
                }
                return;
            }

            openDrawer();

            try {
                await loadKanbanTaskContext(leadProductId);
            } catch (error) {
                console.error(error);
                showError(error.message || 'Aufgaben konnten nicht geladen werden.');
            }
        };

        document.addEventListener('click', async function (event) {
            const closeBtn = event.target.closest('[data-kb-task-close]');
            if (closeBtn) {
                event.preventDefault();
                closeDrawer();
                return;
            }

            const tabBtn = event.target.closest('[data-kb-task-tab]');
            if (tabBtn) {
                event.preventDefault();

                const target = tabBtn.dataset.kbTaskTab;
                document.querySelectorAll('[data-kb-task-tab]').forEach(function (button) {
                    const isActive = button === tabBtn;
                    button.classList.toggle('is-active', isActive);
                    button.setAttribute('aria-selected', isActive ? 'true' : 'false');
                });

                document.querySelectorAll('[data-kb-task-pane]').forEach(function (pane) {
                    pane.classList.toggle('is-active', pane.dataset.kbTaskPane === target);
                });

                if (window.feather) window.feather.replace();
                return;
            }

            const toggleManual = event.target.closest('#customerKanbanManualToggle');
            if (toggleManual) {
                event.preventDefault();
                manualBox?.classList.toggle('is-open');
                return;
            }

            const openBtn = event.target.closest('.open-kanban-task-modal');
            if (openBtn) {
                event.preventDefault();
                event.stopPropagation();

                let leadProductId = openBtn.dataset.leadProductListId || '';

                if (!leadProductId) {
                    const summaryCard = openBtn.closest('.js-profile-kanban-task-summary');
                    leadProductId = summaryCard?.dataset?.leadProductListId || '';
                }

                if (!leadProductId) {
                    const productCard = openBtn.closest('.product-card-body, .custom-responsive-card, .product-status-card');
                    leadProductId = productCard?.querySelector('.js-profile-kanban-task-summary[data-lead-product-list-id]')?.dataset?.leadProductListId || '';
                }

                if (!leadProductId) {
                    if (window.Swal) {
                        Swal.fire({
                            icon: 'error',
                            title: 'LeadProduct-ID fehlt',
                            text: 'Dieser Button braucht lead_product_lists.id. Prüfe im Profil, dass prod.id aus lead_product_lists.* kommt.'
                        });
                    }
                    return;
                }

                openBtn.dataset.leadProductListId = leadProductId;
                await window.openCustomerKanbanTaskDrawer(leadProductId);
                return;
            }

            const statusBtn = event.target.closest('.js-profile-task-status');
            if (statusBtn) {
                event.preventDefault();

                const card = statusBtn.closest('.kb-task-profile-task');
                const taskId = card?.dataset.taskId;
                const status = statusBtn.dataset.status;

                if (!taskId || !status) return;

                try {
                    await fetchJson(`/admin/kanban/tasks/${encodeURIComponent(taskId)}/status`, {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ _token: CSRF_TOKEN, status })
                    });

                    await loadKanbanTaskContext(activeLeadProductId);
                } catch (error) {
                    if (window.Swal) Swal.fire('Fehler', error.message, 'error');
                }
                return;
            }

            const deleteBtn = event.target.closest('.js-profile-task-delete');
            if (deleteBtn) {
                event.preventDefault();

                const card = deleteBtn.closest('.kb-task-profile-task');
                const taskId = card?.dataset.taskId;
                if (!taskId) return;

                let confirmed = true;
                if (window.Swal) {
                    const result = await Swal.fire({
                        icon: 'warning',
                        title: 'Aufgabe löschen?',
                        text: 'Diese Aufgabe wird gelöscht.',
                        showCancelButton: true,
                        confirmButtonText: 'Ja, löschen',
                        cancelButtonText: 'Abbrechen'
                    });
                    confirmed = result.isConfirmed;
                } else {
                    confirmed = confirm('Aufgabe löschen?');
                }

                if (!confirmed) return;

                try {
                    await fetchJson(`/admin/kanban/tasks/${encodeURIComponent(taskId)}`, {
                        method: 'DELETE'
                    });

                    await loadKanbanTaskContext(activeLeadProductId);
                } catch (error) {
                    if (window.Swal) Swal.fire('Fehler', error.message, 'error');
                }
                return;
            }

            const templateBtn = event.target.closest('.js-profile-create-template-task');
            if (templateBtn) {
                event.preventDefault();

                if (!activeLeadProductId) return;

                const options = await askTemplateTaskOptions(templateBtn);
                if (!options) return;

                try {
                    await fetchJson('/admin/kanban/tasks/template', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            _token: CSRF_TOKEN,
                            lead_product_list_id: activeLeadProductId,
                            task_phase_id: templateBtn.dataset.taskPhaseId,
                            phase_activity_id: templateBtn.dataset.phaseActivityId || null,
                            ...options
                        })
                    });

                    await loadKanbanTaskContext(activeLeadProductId);
                } catch (error) {
                    if (window.Swal) Swal.fire('Fehler', error.message, 'error');
                }
            }
        }, true);

        [templateSearchEl, templateSectionFilterEl, templateTypeFilterEl].forEach(function (el) {
            if (!el) return;
            el.addEventListener(el.tagName === 'INPUT' ? 'input' : 'change', applyTemplateFilters);
        });

        if (manualForm) {
            manualForm.addEventListener('submit', async function (event) {
                event.preventDefault();

                if (!activeLeadProductId) return;

                const submitBtn = manualForm.querySelector('[type="submit"]');
                const oldHtml = submitBtn ? submitBtn.innerHTML : '';

                if (submitBtn) {
                    submitBtn.disabled = true;
                    submitBtn.innerHTML = 'Speichern...';
                }

                try {
                    const payload = formPayload(manualForm);
                    payload.lead_product_list_id = activeLeadProductId;

                    await fetchJson('/admin/kanban/tasks/manual', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ _token: CSRF_TOKEN, ...payload })
                    });

                    manualForm.reset();
                    if (leadInput) leadInput.value = activeLeadProductId;
                    if (manualBox) manualBox.classList.remove('is-open');
                    await loadKanbanTaskContext(activeLeadProductId);
                } catch (error) {
                    if (window.Swal) Swal.fire('Fehler', error.message, 'error');
                } finally {
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.innerHTML = oldHtml;
                    }
                }
            });
        }

        document.addEventListener('keydown', function (event) {
            if (event.key === 'Escape' && drawer?.classList.contains('is-open')) {
                closeDrawer();
            }
        });

        document.addEventListener('DOMContentLoaded', scheduleSummaryRefresh);
        window.addEventListener('load', scheduleSummaryRefresh);

        const observer = new MutationObserver(scheduleSummaryRefresh);
        observer.observe(document.body, { childList: true, subtree: true });

        window.refreshProfileKanbanTaskSummaries = refreshProfileKanbanTaskSummaries;
    })();
    </script>



    <script>
    /* =========================================================
       FINAL HARD FIX: Customer notes context loader
       Fixes product sidebar notes and dashboard general notes.

       Source IDs:
       - data-object-product  => product_id / article_groups.id
       - data-pl-id           => lead_product_list_id / lead_product_lists.id

       Required route:
       GET /customer-notes/context/{customer}/{alternative}/{product}/{leadProductList?}
    ========================================================= */
    (function (window, document) {
        'use strict';

        if (window.__MA_CUSTOMER_NOTE_CONTEXT_HARD_FIX__) {
            return;
        }
        window.__MA_CUSTOMER_NOTE_CONTEXT_HARD_FIX__ = true;

        function qs(selector, root) {
            return (root || document).querySelector(selector);
        }

        function qsa(selector, root) {
            return Array.prototype.slice.call((root || document).querySelectorAll(selector));
        }

        function enc(value) {
            return encodeURIComponent(String(value || '').trim());
        }

        function csrf() {
            return qs('meta[name="csrf-token"]')?.getAttribute('content') || window.csrf || '';
        }

        function showNoteError(message) {
            if (window.Swal && typeof window.Swal.fire === 'function') {
                window.Swal.fire('Fehler', message || 'Notizen konnten nicht geladen werden.', 'error');
                return;
            }
            alert(message || 'Notizen konnten nicht geladen werden.');
        }

        function getFirstAlternativeId() {
            var dashboardBtn = qs('.dashboard-btn[data-alternative-id]');
            if (dashboardBtn?.dataset?.alternativeId) return dashboardBtn.dataset.alternativeId;

            var firstObject = qs('.object-thumb-link[data-alternative-id], [data-object-alternative-id], [data-alternative-id]');
            if (firstObject?.dataset?.alternativeId) return firstObject.dataset.alternativeId;
            if (firstObject?.dataset?.objectAlternativeId) return firstObject.dataset.objectAlternativeId;

            return '';
        }

        function getCurrentCustomerId() {
            return qs('#note-list')?.dataset?.customerId ||
                qs('.dashboard-btn[data-customer-id]')?.dataset?.customerId ||
                qs('.project-link[data-object-customer-id]')?.dataset?.objectCustomerId ||
                qs('[data-customer-id]')?.dataset?.customerId ||
                '';
        }

        function getCurrentAlternativeId() {
            return qs('#note-list')?.dataset?.alternativeId ||
                qs('.dashboard-btn[data-alternative-id]')?.dataset?.alternativeId ||
                qs('.project-link.active[data-object-alternative-id]')?.dataset?.objectAlternativeId ||
                qs('.project-link[data-object-alternative-id]')?.dataset?.objectAlternativeId ||
                getFirstAlternativeId() ||
                '';
        }

        function getNoteList() {
            return document.getElementById('note-list');
        }

        function getScrollWrapper() {
            return document.getElementById('note-scroll-wrapper');
        }

        function refreshNoteUi() {
            if (window.feather && typeof window.feather.replace === 'function') {
                window.feather.replace();
            }
            if (typeof window.initNoteListeners === 'function') {
                window.initNoteListeners();
            }
        }

        function rememberContext(ctx) {
            var noteList = getNoteList();
            if (!noteList) return;

            noteList.dataset.customerId = ctx.customerId || '';
            noteList.dataset.alternativeId = ctx.alternativeId || '';
            noteList.dataset.productId = ctx.productId || '';
            noteList.dataset.genericId = ctx.productId || '';
            noteList.dataset.uniqueId = ctx.leadProductListId || '';
            noteList.dataset.noteType = ctx.noteType || 'general';
        }

        function markActiveProduct(card) {
            qsa('.project-link, .project-card, .ma-product-card').forEach(function (el) {
                el.classList.remove('active', 'is-open');
            });
            if (card) card.classList.add('active', 'is-open');
        }

        async function setNotesHtml(url, ctx, loadingText) {
            var noteList = getNoteList();
            var scrollWrapper = getScrollWrapper();

            if (!noteList) {
                showNoteError('Notizbereich wurde nicht gefunden.');
                return false;
            }

            rememberContext(ctx);
            noteList.innerHTML = '<div class="text-muted p-3">' + (loadingText || 'Lade Notizen...') + '</div>';

            try {
                var response = await fetch(url, {
                    method: 'GET',
                    headers: {
                        'Accept': 'text/html',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    credentials: 'same-origin'
                });

                if (!response.ok) {
                    throw new Error('Serverantwort war nicht erfolgreich.');
                }

                var html = await response.text();

                var parsed = document.createElement('div');
                parsed.innerHTML = html;

                var returnedNoteList = parsed.querySelector('#note-list');
                if (returnedNoteList) {
                    noteList.innerHTML = returnedNoteList.innerHTML;
                } else {
                    noteList.innerHTML = html;
                }

                rememberContext(ctx);
                refreshNoteUi();

                if (scrollWrapper) {
                    setTimeout(function () {
                        scrollWrapper.scrollTo({ top: 0, behavior: 'smooth' });
                    }, 80);
                }

                return true;
            } catch (error) {
                console.error('Customer note load failed:', error, { url: url, ctx: ctx });
                noteList.innerHTML = '<div class="text-danger p-3">Fehler beim Laden der Notizen.</div>';
                return false;
            }
        }

        window.maLoadProductNotesFromCard = async function (card) {
            if (!card) return false;

            var customerId = card.dataset.objectCustomerId || card.dataset.customerId || getCurrentCustomerId();
            var alternativeId = card.dataset.objectAlternativeId || card.dataset.alternativeId || getCurrentAlternativeId();
            var productId = card.dataset.objectProduct || card.dataset.productId || card.dataset.genericId || '';
            var leadProductListId = card.dataset.plId || card.dataset.leadProductListId || card.dataset.productListId || '';

            if (!customerId || !alternativeId || !productId) {
                console.error('Missing product note context', { customerId, alternativeId, productId, leadProductListId, card });
                showNoteError('Kunde, Objekt oder Produkt fehlt.');
                return false;
            }

            markActiveProduct(card);

            var title = document.getElementById('note_title');
            if (title) title.textContent = 'PRODUKT NOTIZEN';

            var subNav = card.dataset.productKey ? document.getElementById(card.dataset.productKey) : null;
            if (subNav) {
                qsa('.sub-nav').forEach(function (el) {
                    if (el !== subNav) {
                        el.classList.remove('show');
                        el.style.display = 'none';
                    }
                });
                subNav.classList.add('show');
                subNav.style.display = 'block';
            }

            var ctx = {
                customerId: customerId,
                alternativeId: alternativeId,
                productId: productId,
                leadProductListId: leadProductListId,
                noteType: 'product'
            };

            var url = '/customer-notes/context/' + enc(customerId) + '/' + enc(alternativeId) + '/' + enc(productId) + '/' + enc(leadProductListId);
            return setNotesHtml(url, ctx, 'Lade Produkt-Notizen...');
        };

        window.maLoadGeneralCustomerNotes = async function (source) {
            var sourceEl = source && source.dataset ? source : null;
            var customerId = sourceEl?.dataset?.customerId || getCurrentCustomerId();
            var alternativeId = sourceEl?.dataset?.alternativeId || getCurrentAlternativeId();

            if (!customerId || !alternativeId) {
                console.error('Missing general note context', { customerId, alternativeId, source: source });
                showNoteError('Kunde oder Objekt fehlt.');
                return false;
            }

            qsa('.project-link, .project-card, .ma-product-card').forEach(function (el) {
                el.classList.remove('active', 'is-open');
            });

            var title = document.getElementById('note_title');
            if (title) title.textContent = 'KUNDENCHAT';

            var ctx = {
                customerId: customerId,
                alternativeId: alternativeId,
                productId: '',
                leadProductListId: '',
                noteType: 'general'
            };

            return setNotesHtml('/customer-notes/' + enc(customerId) + '/' + enc(alternativeId) + '/0', ctx, 'Lade allgemeine Notizen...');
        };

        window.maEnsureNoteContext = function () {
            var noteList = getNoteList();
            var activeCard = qs('.project-link.active[data-object-customer-id], .project-card.active[data-object-customer-id], .ma-product-card.active[data-object-customer-id]');

            var ctx = {
                customerId: noteList?.dataset?.customerId || activeCard?.dataset?.objectCustomerId || getCurrentCustomerId(),
                alternativeId: noteList?.dataset?.alternativeId || activeCard?.dataset?.objectAlternativeId || getCurrentAlternativeId(),
                leadProductListId: noteList?.dataset?.uniqueId || activeCard?.dataset?.plId || activeCard?.dataset?.leadProductListId || '',
                productId: noteList?.dataset?.genericId || noteList?.dataset?.productId || activeCard?.dataset?.objectProduct || activeCard?.dataset?.productId || '',
                noteType: noteList?.dataset?.noteType || ((activeCard?.dataset?.plId || activeCard?.dataset?.objectProduct) ? 'product' : 'general')
            };

            if (ctx.noteType === 'general') {
                ctx.productId = '';
                ctx.leadProductListId = '';
            }

            rememberContext(ctx);
            return {
                customerId: String(ctx.customerId || ''),
                alternativeId: String(ctx.alternativeId || ''),
                uniqueId: String(ctx.leadProductListId || ''),
                genericId: String(ctx.productId || ''),
                noteType: String(ctx.noteType || 'general')
            };
        };

        window.toggleProduct = function (productKey) {
            var card = qs('.project-link[data-product-key="' + String(productKey || '').replace(/"/g, '\\"') + '"], .project-card[data-product-key="' + String(productKey || '').replace(/"/g, '\\"') + '"]');
            if (card) {
                return window.maLoadProductNotesFromCard(card);
            }
            return false;
        };

       async function maLoadCustomerDashboard(source) {
    var sourceEl = source && source.dataset
        ? source
        : qs('button.dashboard-btn[data-customer-id][data-alternative-id]');

    var customerId = sourceEl?.dataset?.customerId || getCurrentCustomerId();
    var alternativeId = sourceEl?.dataset?.alternativeId || getCurrentAlternativeId();

    if (!customerId || !alternativeId) {
        if (window.Swal) {
            window.Swal.fire('Fehler', 'Kunde oder Alternative fehlt.', 'error');
        } else {
            alert('Kunde oder Alternative fehlt.');
        }
        return false;
    }

    var mainContent = document.getElementById('mainContent');
    if (!mainContent) {
        console.error('#mainContent not found.');
        return false;
    }

    mainContent.innerHTML = '<div class="text-muted p-2">Dashboard wird geladen...</div>';

    try {
        var response = await fetch('/dashboard/customer/' + enc(customerId) + '/alternative/' + enc(alternativeId), {
            method: 'GET',
            headers: {
                'Accept': 'text/html',
                'X-Requested-With': 'XMLHttpRequest'
            },
            credentials: 'same-origin'
        });

        if (!response.ok) {
            throw new Error('Dashboard konnte nicht geladen werden.');
        }

        var html = await response.text();
        mainContent.innerHTML = html;

        if (window.feather && typeof window.feather.replace === 'function') {
            window.feather.replace();
        }

        if (typeof window.initDashboardListeners === 'function') {
            window.initDashboardListeners();
        }

        if (typeof window.loadDashboard === 'function') {
            window.loadDashboard();
        }

        return true;
    } catch (error) {
        console.error('Dashboard load failed:', error);
        mainContent.innerHTML = '<div class="text-danger p-2">Fehler beim Laden des Dashboards.</div>';
        return false;
    }
}

window.maLoadCustomerDashboard = maLoadCustomerDashboard;

window.showDashboard = async function (btn) {
    btn = btn && btn.dataset
        ? btn
        : qs('button.dashboard-btn[data-customer-id][data-alternative-id]');

    await maLoadCustomerDashboard(btn);

    if (typeof window.maLoadGeneralCustomerNotes === 'function') {
        await window.maLoadGeneralCustomerNotes(btn);
    }

    return false;
};

document.addEventListener('click', function (event) {
    var btn = event.target.closest('button.dashboard-btn[data-customer-id][data-alternative-id]');
    if (!btn) return;

    event.preventDefault();
    event.stopPropagation();
    if (typeof event.stopImmediatePropagation === 'function') {
        event.stopImmediatePropagation();
    }

    window.showDashboard(btn);
    return false;
}, true);

        document.addEventListener('click', function (event) {
            var btn = event.target.closest('.dashboard-btn');
            if (!btn) return;

            event.preventDefault();
            event.stopPropagation();
            if (typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();

            window.maLoadGeneralCustomerNotes(btn);
            return false;
        }, true);

        var oldToggleNewNoteArea = window.toggleNewNoteArea;
        window.toggleNewNoteArea = function (event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            window.maEnsureNoteContext();

            if (typeof oldToggleNewNoteArea === 'function') {
                return oldToggleNewNoteArea(event);
            }

            var composer = document.getElementById('newNoteComposer');
            var backdrop = document.getElementById('noteBackdrop');
            if (!composer || !backdrop) return false;

            var isOpen = composer.classList.contains('open');
            if (isOpen && typeof window.closeComposer === 'function') {
                window.closeComposer();
                return false;
            }

            composer.classList.add('open');
            backdrop.style.display = 'block';
            setTimeout(function () {
                document.getElementById('newNoteText')?.focus();
            }, 80);
            return false;
        };

        window.submitNote = async function () {
            var input = document.getElementById('newNoteText');
            var container = getNoteList();
            var btn = qs('#newNoteComposer button[onclick*="submitNote"], #newNoteComposer button[type="button"], #newNoteComposer button');
            var text = (input?.value || '').trim();

            if (!text) {
                if (window.Swal) return window.Swal.fire('Hinweis', 'Bitte eine Notiz eingeben.', 'warning');
                alert('Bitte eine Notiz eingeben.');
                return false;
            }

            if (!container) {
                showNoteError('Notizbereich wurde nicht gefunden.');
                return false;
            }

            var ctx = window.maEnsureNoteContext();

            if (!ctx || !ctx.customerId || !ctx.alternativeId) {
                showNoteError('Kunde oder Alternative fehlt. Bitte zuerst Dashboard oder ein Produkt im linken Menü öffnen.');
                return false;
            }

            var payload = {
                customer_id: ctx.customerId,
                alternative_id: ctx.alternativeId,
                lead_product_list_id: ctx.noteType === 'product' ? (ctx.uniqueId || null) : null,
                product_id: ctx.noteType === 'product' ? (ctx.genericId || null) : null,
                type: ctx.noteType || 'general',
                description: text,
                priority: 'normal',
                color: '#cfe09b'
            };

            var oldHtml = btn ? btn.innerHTML : '';
            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Senden...';
            }

            try {
                var response = await fetch('/customer-notes/store', {
                    method: 'POST',
                    headers: {
                        'X-CSRF-TOKEN': csrf(),
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify(payload)
                });

                var data = await response.json().catch(function () { return {}; });

                if (!response.ok || !data.success) {
                    throw new Error(data.message || 'Notiz konnte nicht gespeichert werden.');
                }

                if (data.html) {
                    container.insertAdjacentHTML('afterbegin', data.html);
                } else if (payload.type === 'general') {
                    await window.maLoadGeneralCustomerNotes(qs('.dashboard-btn'));
                } else {
                    var activeCard = qs('.project-link.active[data-object-product], .project-card.active[data-object-product], .ma-product-card.active[data-object-product]');
                    if (activeCard) await window.maLoadProductNotesFromCard(activeCard);
                }

                if (input) input.value = '';
                if (typeof window.closeComposer === 'function') window.closeComposer();
                refreshNoteUi();
            } catch (error) {
                console.error('Submit note failed:', error, payload);
                showNoteError(error.message || 'Notiz konnte nicht gespeichert werden.');
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = oldHtml || '<i class="feather icon-send me-1"></i> Senden';
                }
            }

            return false;
        };

        document.addEventListener('DOMContentLoaded', function () {
            var noteList = getNoteList();
            var dashboardBtn = qs('.dashboard-btn');
            if (noteList && dashboardBtn) {
                if (!noteList.dataset.customerId && dashboardBtn.dataset.customerId) noteList.dataset.customerId = dashboardBtn.dataset.customerId;
                if (!noteList.dataset.alternativeId && dashboardBtn.dataset.alternativeId) noteList.dataset.alternativeId = dashboardBtn.dataset.alternativeId;
            }
            window.maEnsureNoteContext();
        });
    })(window, document);
    </script>



    <script>
    /* =========================================================
       Object + Context Feed Collapse Scroll Fix
       Put this AFTER all old profile scripts and customer-context-feed.js
    ========================================================= */
    (function (window, document) {
        'use strict';

        if (window.__MA_OBJECT_CONTEXT_COLLAPSE_FIX__) {
            return;
        }
        window.__MA_OBJECT_CONTEXT_COLLAPSE_FIX__ = true;

        function cssEscape(value) {
            if (window.CSS && typeof window.CSS.escape === 'function') {
                return window.CSS.escape(String(value));
            }
            return String(value).replace(/([ #;?%&,.+*~\':"!^$[\]()=>|/@])/g, '\\$1');
        }

        function refreshIcons() {
            if (window.feather && typeof window.feather.replace === 'function') {
                window.feather.replace();
            }
        }

        function isVisible(el) {
            if (!el) return false;
            return el.classList.contains('show') || el.classList.contains('is-open') || window.getComputedStyle(el).display !== 'none';
        }

        function findObjectList(target) {
            if (!target) return null;

            if (typeof target === 'string') {
                return document.getElementById(target) || document.querySelector('#' + cssEscape(target));
            }

            if (target.classList && (target.classList.contains('product-list') || target.classList.contains('ma-product-list'))) {
                return target;
            }

            var header = target.closest ? target.closest('.object-header') : null;
            if (header) {
                var next = header.nextElementSibling;
                while (next) {
                    if (next.classList && (next.classList.contains('product-list') || next.classList.contains('ma-product-list'))) {
                        return next;
                    }
                    next = next.nextElementSibling;
                }
            }

            return null;
        }

        function findObjectHeader(list) {
            if (!list) return null;
            var prev = list.previousElementSibling;
            while (prev) {
                if (prev.classList && prev.classList.contains('object-header')) {
                    return prev;
                }
                prev = prev.previousElementSibling;
            }
            return list.closest('.object-section')?.querySelector('.object-header') || null;
        }

        function setObjectState(list, open) {
            if (!list) return;

            var header = findObjectHeader(list);
            var wrapper = list.closest('.object-section');

            list.classList.toggle('show', !!open);
            list.classList.toggle('is-open', !!open);
            list.style.display = open ? 'block' : 'none';
            list.setAttribute('aria-hidden', open ? 'false' : 'true');

            if (header) {
                header.classList.toggle('is-open', !!open);
                header.setAttribute('aria-expanded', open ? 'true' : 'false');
            }

            if (wrapper) {
                wrapper.classList.toggle('is-open', !!open);
            }
        }

        function closeObjectList(list) {
            setObjectState(list, false);
        }

        function closeSubNavs(scope) {
            (scope || document).querySelectorAll('.sub-nav, .ma-sub-nav').forEach(function (sub) {
                sub.classList.remove('show', 'is-open');
                sub.style.display = 'none';
                sub.setAttribute('aria-hidden', 'true');
            });

            (scope || document).querySelectorAll('.project-link.active, .project-card.active, .ma-product-card.active').forEach(function (card) {
                card.classList.remove('active', 'is-open');
            });
        }

        window.toggleObject = function (target) {
            var list = findObjectList(target);
            if (!list) return false;

            var sidebar = list.closest('.customerSidebar') || document;
            var shouldOpen = !isVisible(list);

            sidebar.querySelectorAll('.product-list, .ma-product-list').forEach(function (other) {
                if (other !== list) {
                    closeObjectList(other);
                }
            });

            closeSubNavs(sidebar);
            setObjectState(list, shouldOpen);

            if (shouldOpen) {
                setTimeout(function () {
                    list.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                }, 80);
            }

            refreshIcons();
            return shouldOpen;
        };

        window.toggleProduct = function (target) {
            var subNav = null;
            var card = null;

            if (typeof target === 'string') {
                subNav = document.getElementById(target) || document.querySelector('#' + cssEscape(target));
                card = document.querySelector('[data-product-key="' + cssEscape(target) + '"]');
            } else if (target && target.closest) {
                card = target.closest('.project-link, .project-card, .ma-product-card');
                var key = card ? card.getAttribute('data-product-key') : null;
                subNav = key ? document.getElementById(key) : null;
            }

            if (!subNav) return false;

            var parentList = subNav.closest('.product-list, .ma-product-list');
            if (parentList && !isVisible(parentList)) {
                window.toggleObject(parentList);
            }

            var shouldOpen = !isVisible(subNav);
            var scope = parentList || document;

            scope.querySelectorAll('.sub-nav, .ma-sub-nav').forEach(function (other) {
                if (other !== subNav) {
                    other.classList.remove('show', 'is-open');
                    other.style.display = 'none';
                    other.setAttribute('aria-hidden', 'true');
                }
            });

            scope.querySelectorAll('.project-link.active, .project-card.active, .ma-product-card.active').forEach(function (otherCard) {
                if (otherCard !== card) {
                    otherCard.classList.remove('active', 'is-open');
                }
            });

            subNav.classList.toggle('show', shouldOpen);
            subNav.classList.toggle('is-open', shouldOpen);
            subNav.style.display = shouldOpen ? 'block' : 'none';
            subNav.setAttribute('aria-hidden', shouldOpen ? 'false' : 'true');

            if (card) {
                card.classList.toggle('active', shouldOpen);
                card.classList.toggle('is-open', shouldOpen);
            }

            if (shouldOpen) {
                setTimeout(function () {
                    subNav.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                }, 80);
            }

            refreshIcons();
            return shouldOpen;
        };

        /* Prevent old inline onclick="toggleObject('object0')" from double-firing. */
        document.addEventListener('click', function (event) {
            var header = event.target.closest('.customerSidebar .object-header');
            if (!header) return;

            if (event.target.closest('a, button, input, select, textarea, label, .sidebar-gallery, .object-thumb-link, [data-no-object-toggle]')) {
                return;
            }

            event.preventDefault();
            event.stopPropagation();
            if (typeof event.stopImmediatePropagation === 'function') {
                event.stopImmediatePropagation();
            }

            window.toggleObject(header);
        }, true);

        document.addEventListener('keydown', function (event) {
            if (event.key !== 'Enter' && event.key !== ' ') return;

            var header = event.target.closest('.customerSidebar .object-header');
            if (!header) return;

            event.preventDefault();
            window.toggleObject(header);
        }, true);

        /* Context feed collapse: scroll the opened body into readable position. */
        document.addEventListener('click', function (event) {
            var head = event.target.closest('#note-list .ma-feed-head, #note-list [data-feed-collapse]');
            if (!head) return;

            var card = head.closest('.ma-feed-card');
            if (!card) return;

            setTimeout(function () {
                if (!card.classList.contains('is-open')) return;
                var body = card.querySelector('.ma-feed-body');
                (body || card).scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }, 120);
        }, false);

        document.addEventListener('DOMContentLoaded', function () {
            document.querySelectorAll('.customerSidebar .product-list, .customerSidebar .ma-product-list').forEach(function (list) {
                var open = isVisible(list) && list.style.display !== 'none';
                setObjectState(list, open);
            });
            refreshIcons();
        });
    })(window, document);
    </script>
    <script src="{{ asset('js/object-context-menu-final.js') }}?v={{ time() }}"></script>
